\label{maintheorem}
Assume that $k\ge2$, $\phi_1\not\equiv0$ and \eqref{gh}--\eqref{g00} hold.
Let $T_\delta$ denote the lifespan of the smooth solution $\phi$.
Then we have
\begin{enumerate}[label=(\roman*)]
\item when $\varepsilon_k^*<\varepsilon_0<1$, for small $\delta>0$, the solution $\phi$ develops a singularity in finite time, and
\begin{equation}\label{lifespan}
\limsup_{\delta\to0^+}
\delta^{(k+1)(\varepsilon_k^*-\varepsilon_0)}(T_\delta-1)
\le\frac{2}{(k+1)\Xi}.
\end{equation}
\item when $\varepsilon_0=\varepsilon_k^*$ and \eqref{critical-compression}
holds, for small $\delta>0$,  the solution $\phi$ will blow up in finite time and
\begin{equation}\label{critical-lifespan}
\limsup_{\delta\to0^+}T_\delta
\le S_{\mathrm{crit}}
:=\big(1-\frac{k-1}{(k+1)\Xi}\big)^{-\frac{2}{k-1}}.
\end{equation}
\end{enumerate}

\label{Yin.4}
If the inverse foliation density $\mu$ (see its definition in \eqref{DXY-1} below), which measures the compression of the characteristics, has a positive lower bound,
through establishing uniform bounds for the relevant energies and geometric quantities,
then one can conclude that the equation in \eqref{quasi-0} equipped with short pulse data
admits a global smooth solution $v$ (see \cite{DLY}-\cite{Ding4}, \cite{MPY} and \cite{Wang}).
In addition, the authors of \cite{An-1, An-2} apply the Lorentzian geometric tools from \cite{Ch1}
to study the local well-posedness or ill-posedness of low regularity solutions to the elastic wave system.
On the other hand, based on the Lorentzian geometric methods, the authors of \cite{Luo-Yu-1, Luo-Yu-2}
have shown the structural stability in the regime of two families of rarefaction waves
for multi-dimensional compressible isentropic and irrotational Euler equations.

\label{Local}
Under the assumptions \eqref{gh}--\eqref{g00}, when $\delta>0$ is small, \eqref{quasi} with \eqref{id}
admits a local smooth solution $\phi\in C^\infty([1, t_0]\times\mathbb R^2)$. Moreover,
for $m,p\in\mathbb N_0$, $\kappa\in\mathbb N_0^3$, it holds that
\begin{equation}\label{initial}
|L^m\partial^\kappa\Omega^p\phi(t_0,x)|\lesssim\delta^{2-\varepsilon0-m\varepsilon_k-|\kappa|},\quad r \in[1-2\delta, 1+2\delta].
\end{equation}
In addition, at any point $(t_0, r\omega)$, we have
\begin{align}
&\delta^{\varepsilon_0-1}\underline L\phi(t_0, r\omega) = 2\phi_1\big(\tfrac{r-t_0}{\delta}, \omega\big) + O(\delta^{(k+1)(1-\varepsilon0)}),\label{Lphi}\\
&\delta^{\varepsilon_0}\underline L\partial_0\phi(t_0, r\omega) = -2\partial_\sigma\phi_1\big(\tfrac{r-t_0}{\delta}, \omega\big) + O(\delta^{(k+1)(1-\varepsilon0)}).\label{y0}
\end{align}

Denote by $Z_g$ any fixed vector field in $\{S, H_1, H_2\}$.
Suppose that for $1\leq t\leq t_0$
and $N_0\in\mathbb N_0$ with $N_0\ge 6$, one has
	\begin{equation}\label{ba}
	|\partial^\kappa\Omega^pZ_g^\nu\phi|\leq\delta^{2-\epsilon-|\nu|\varepsilon_k-|\kappa|}\quad (|\kappa|+p+|\nu|\leq N_0,\quad |\nu|\leq 1),
	\end{equation}
where $\epsilon\in(\varepsilon0, 1)$ is a fixed constant.
Define the following energy for \eqref{quasi} and for $n\in\mathbb N_0$,
$$
M_n(t)=\sum_{\tiny\begin{array}{c}|\kappa|+p+|\nu|\leq n\\|\nu|\leq 1\end{array}}\delta^{2|\kappa|+2|\nu|\varepsilon_k}\|\partial\partial^\kappa\Omega^pZ_g^\nu\phi(t,\cdot)\|_{L^2(\mathbb R^2)}^2.
$$

Let $w=\delta^{|\kappa|+|\nu|\varepsilon_k}\partial^\kappa\Omega^pZ_g^\nu\phi\quad(|\kappa|+p+|\nu|\leq 2N_0-2)$. It follows from \eqref{quasi}
and integration by parts that
\begin{equation}\label{Y-4}
\begin{split}
&\int_1^t\int_{\Sigma_\tau}(\partial_twg^{\alpha\beta}\partial_{\alpha\beta}^2w)(\tau,x) dxd\tau\\
=&\int_{\Sigma_{t}}\big(g^{0\alpha}\partial_\alpha w\partial_t w-\frac12g^{\alpha\beta}\partial_\alpha w\partial_\beta w\big)(t,x)dx-\int_{\Sigma_{1}}\big(g^{0\alpha}\partial_\alpha w\partial_t w-\frac12g^{\alpha\beta}\partial_\alpha w\partial_\beta w\big)(1,x)dx\\
&+\int_1^t\int_{\Sigma_\tau}\big(-(\partial_\alpha g^{\alpha\beta})\partial_\beta w\partial_t w+\frac12(\partial_tg^{\alpha\beta})\partial_\alpha w\partial_\beta w\big)(\tau,x) dxd\tau
\end{split}
\end{equation}
with
\begin{equation}\label{w}
\begin{split}
|g^{\alpha\beta}&\partial_{\alpha\beta}^2w|\lesssim\delta^{|\kappa|+|\nu|\varepsilon_k}\sum_{\tiny\begin{array}{c}
	|\kappa_1|+|\kappa_2|\leq|\kappa|,\ p_1+p_2\leq p,\\|\nu_1|+|\nu_2|\leq|\nu|,\\ |\kappa_2|+p_2+|\nu_2|<|\kappa|+p+|\nu|\end{array}}|\partial^{\kappa_1}\Omega^{p_1}Z_g^{\nu_1}	(g^{\alpha\beta}-m^{\alpha\beta})||\partial^{\kappa_2}\Omega^{p_2}Z_g^{\nu_2}\partial^2\phi|.
\end{split}
\end{equation}
By \eqref{ba}-\eqref{w} and Gronwall's inequality, we obtain that for $1\leq t\leq t_0$,
$$
M_{2N_0-2}(t)\lesssim M_{2N_0-2}(1)\lesssim\delta^{3-2\varepsilon_0}.
$$
In addition, by the following Sobolev embedding theorem on the circle $\mathbb S_r$
	(with center at the origin and radius $r$), one has that
	$$
	|w(t,x)|\lesssim \frac{1}{\sqrt{r}}\|\Omega^{\leq 1}w\|_{L^2(\mathbb S_r)}.
	$$
This, together with $r\sim 1$ for $t\in [1,t_0]$ and $(t,x)\in \textrm{supp}\ w$, yields that when $|\kappa|+p+|\nu|\leq N_0$,
	\begin{equation}\label{le}
	|\partial^\kappa\Omega^pZ_g^\nu\phi(t,x)|\lesssim \|\Omega^{\leq 1}\partial^\kappa\Omega^pZ_g^\nu\phi\|_{L^2(\mathbb S_r)}\lesssim\delta^{1/2}\|\partial\Omega^{\leq 1}\partial^\kappa\Omega^pZ_g^\nu\phi\|_{L^2(\Sigma_{t})}\lesssim\delta^{2-|\kappa|-\varepsilon_0-|\nu|\varepsilon_k},\quad
	\end{equation}
	where $N_0\geq 6$ has been used. Therefore, \eqref{ba} can be closed
	for suitably small $\delta>0$ and $\epsilon>\varepsilon_0$.
	
	
Next we improve the $L^\infty$ estimate of $\phi(t_0,x)$ on some special space domains. To this end,
one rewrites \eqref{quasi} as
\begin{equation}\label{me}
L\underline L\phi=\frac{1}{2r}L\phi-\frac{1}{2r}\underline L\phi+\frac{1}{r^2}\Omega^2\phi+g^{\alpha\beta,
	\gamma_1,\cdots,\gamma_k}(\partial_{\gamma_1}\phi)\cdots(\partial_{\gamma_k}\phi)\partial^2_{\alpha\beta}\phi+h^{\alpha\beta}(\partial\phi)\partial^2_{\alpha\beta}\phi.
\end{equation}


Applying the operator $L\bar\partial^{\iota}\Omega^p$ to both sides of \eqref{me}, where $\bar\partial\in\{\partial_t,\partial_r\}$ and $\iota\in\mathbb N_0^2$,
we can obtain an expression of $\underline LL^2\bar\partial^{\iota}\Omega^p\phi$ by $\underline LL^2\bar\partial^{\iota}\Omega^p=L\bar\partial^{\iota}\Omega^pL\underline L$  and a direct computation.
Together with \eqref{le}, this implies that for $|\iota|+p\leq 2N_0-6$,
\begin{equation}\label{nonull}
	|\underline L(L^2\bar\partial^{\iota}\Omega^p\phi)|\lesssim \delta^{-2\varepsilon_k-|\iota|},
\end{equation}
here  the null condition \eqref{null} is not used. Due to the vanishing property of $\phi$ on $\{(t, x): t\ge 1, t=r\}$,
integrating \eqref{nonull} along the integral curves of $\underline L$ yields that for $(t,r)\in D^1=\{(t,r): 1\le t\le t_0, 2-t\le r\le t\}$ and for $|\iota|+p\leq 2N_0-6$,
\begin{equation}\label{D}
|L^2\bar\partial^{\iota}\Omega^p\phi(t,x)|\lesssim\delta^{1-2\varepsilon_k-|\iota|}.
\end{equation}
Using the equation for $\underline LL^2\bar\partial^{\iota}\Omega^p\phi$ again, together with \eqref{null} and
\eqref{D}, gives $|\underline L(L^2\bar\partial^{\iota}\Omega^p\phi) |\lesssim\delta^{1-\varepsilon_0-2\varepsilon_k-|\iota|}$ for $\varepsilon_k^*\leq\varepsilon_0<1$ and $|\iota|+p\leq2N_0-7$. This means that for $(t,x)\in D^1$,
\begin{equation}\label{D-1}
|L^2\bar\partial^{\iota}\Omega^p\phi(t,x)|\lesssim\delta^{2-\varepsilon_0-2\varepsilon_k-|\iota|},\quad|\iota|+p\leq2N_0-7.
\end{equation}
Then it follows from an induction argument and \eqref{me} that for $(t,x)\in D^1$,
 \begin{equation}\label{oi}
|L^m\bar\partial^\iota\Omega^p\phi(t,x)|\lesssim\delta^{2-\varepsilon_0-m\varepsilon_k-|\iota|},\quad 3m+|\iota|+p\leq 2N_0-4,
\end{equation}
which yields \eqref{initial} due to $\partial_i=\omega^i\partial_r+\frac{\omega_\perp^i}r\Omega$ ($i=1,2$).



Note that both the points $(1,(r_0-t_0+1)\omega)$ and $(t_0, r_0\omega)$ are on the line $\{(t,r\omega): r-t=r_0-t_0\}$.
Then, by \eqref{me}, \eqref{le} and \eqref{id}, we arrive at
\begin{equation*}
\begin{split}
&\underline{L}\phi(t_0,r_0\omega)
=\underline{L}\phi(1,(r_0-t_0+1)\omega)+\int_{(1,(r_0-t_0+1)\omega)}^{(t_0,r_0\omega)}L\underline{L}\phi\\
=&\delta^{1-\varepsilon_0}\big(\phi_1\big(\frac{r_0-t_0}{\delta}, \omega\big)-\partial_\sigma\phi_0\big(\frac{r_0-t_0}{\delta}, \omega\big)\big)+O(\delta^{(k+2)(1-\varepsilon_0)})\\
=&2\delta^{1-\varepsilon_0}\phi_1\big(\frac{r_0-t_0}{\delta}, \omega\big)+O(\delta^{(k+2)(1-\varepsilon_0)})
\end{split}
\end{equation*}
and
\begin{equation*}
\begin{split}
&\underline{L}\partial_{0}\phi(t_0,r_0\omega)
=\underline{L}\partial_{0}\phi(1,(r_0-t_0+1)\omega)+\int_{(1,(r_0-t_0+1)\omega)}^{(t_0,r_0\omega)}L\underline{L}\partial_{0}\phi\\
=&\delta^{-\varepsilon_0}\big(\partial_\sigma^2\phi_0\big(\frac{r_0-t_0}{\delta}, \omega\big)-\partial_\sigma\phi_1\big(\frac{r_0-t_0}{\delta}, \omega\big)\big)+O(\delta^{(k+1)(1-\varepsilon_0)-\varepsilon_0})\\
=&-2\delta^{-\varepsilon_0}\partial_\sigma\phi_1\big(\frac{r_0-t_0}{\delta}, \omega\big)+O(\delta^{(k+1)(1-\varepsilon_0)-\varepsilon_0}).
\end{split}
\end{equation*}
Hence, \eqref{Lphi} and \eqref{y0} are shown.

\label{Definition optical function}
	A $C^1$ function $u(t,x)$ is called the optical function of \eqref{quasi} if $u(t,x)$ satisfies the eikonal equation
	\begin{equation}\label{eikonal equation}
	g^{\alpha\beta}\partial_{\alpha}u\partial_{\beta}u=0
	\end{equation}
	with the initial data $u(t_0,x)=t_0-r$ and the condition $\partial_{0}u>0$.

\label{nullframe}
$\{\mathring L, \mathring{\underline L}, X\}$ constitutes a null frame with respect to the metric $(g_{\alpha\beta})$, and admits the following identities:
\begin{align*}
g(\mathring L,\mathring L)=g(\mathring{\underline L}, \mathring{\underline L})=g(\mathring L, X)=g(\mathring{\underline L}, X)=0,
g(\mathring L, \mathring{\underline L})=-2\mu.
\end{align*}
In addition,
\begin{align*}
\mathring L t=1,\quad\mathring L u=0,\quad
\mathring{\underline L}t=\mu,\quad \mathring{\underline L} u=2.
\end{align*}
And
\begin{align}\label{LTTT}
g(\mathring L, T)=-\mu,\quad g(T,T)=\mu^2,
\end{align}
\begin{align}\label{T}
Tt=0,\quad T u=1.
\end{align}

\begin{equation*}
\begin{split}
&\Sigma_s=\{(s',u',\vartheta): s'=s, u'>0\},\\
&\Sigma_s^{u}=\{(s',u',\vartheta): s'=s,0\leq u'\leq  u\},\quad u\in [0, 4\delta],\\
&C_{u}=\{(s',u',\vartheta): s'\geq 1+2\delta, u'=u\},\\
&C_{u}^s=\{(s',u',\vartheta): 1+2\delta\leq s'\leq s, u'=u\},\\
&S_{s, u}=\Sigma_s\cap C_{u},\\
&D^{s, u}=\{(s', u',\vartheta): 1+2\delta\leq s'<s, 0\leq u'\leq u\}.
\end{split}
\end{equation*}

For the metric $g$ on the spacetime,
\begin{itemize}
\item $\underline g=(g_{ij})$ is defined as the induced metric of $g$ on $\Sigma_s$, i.e.,
$\underline g(U,V)=g(U,V)$ for any tangent vectors $U$ and $V$ of $\Sigma_s$;
\item $\slashed \Pi_\alpha^\beta=\delta_\alpha^\beta-\delta_\alpha^0\mathring L^\beta+\mathring L_\alpha\tilde{T}^\beta$ is the
projection tensor field on $S_{s,u}$ of type $(1,1)$, where $\delta_\alpha^\beta$ is the Kronecker delta;
\item For any $(m,n)$-type
spacetime tensor field
$\eta$, $\slashed\eta=\slashed\Pi\eta$ is the tensor field on $S_{s,u}$  with the components $$\slashed\eta^{\alpha_1\cdots\alpha_m}_{\beta_1\cdots\beta_n}:=(\slashed\Pi\eta)^{\alpha_1\cdots\alpha_m}_{\beta_1\cdots\beta_n}
=\slashed\Pi_{\beta_1}^{\beta_1'}\cdots\slashed\Pi_{\beta_n}^{\beta_n'}
\slashed\Pi_{\alpha_1'}^{\alpha_1}\cdots\slashed\Pi_{\alpha_m'}^{\alpha_m}\eta^{\alpha_1'\cdots\alpha_m'}_{\beta_1'\cdots\beta_n'}.$$
In particular, $\slashed g=(\slashed g_{\alpha\beta})$ is the induced metric of $g$ on $S_{s,u}$;
\item $\slashed g^{XX}$ is defined as the inverse of $\slashed g_{XX}$ with $\slashed g_{XX}=g(X, X)$;
\item $\mathscr D$ and $\slashed\nabla$ denote the Levi-Civita connections of $g$ and $\slashed g$, respectively;
\item $\Box_g=g^{\alpha\beta}\mathscr{D}^2_{\alpha\beta}$, \quad $\slashed\triangle=\slashed g^{XX}\slashed\nabla^2_{X}$;
\item $\mathcal L_V\eta$ is the Lie derivative of $\eta$ with respect to $V$
and $\slashed{\mathcal L}_V\eta=\slashed\Pi(\mathcal L_V\eta)$ for any tensor field $\eta$ and vector $V$;
\item For any $(m,n)$-type spacetime tensor field $\eta$,
$$
|\eta|^2=g_{\alpha_1\alpha_1'}\cdots g_{\alpha_m\alpha_m'}g^{\beta_1\beta_1'}\cdots g^{\beta_n\beta_n'}\eta_{\beta_1\cdots\beta_n}^{\alpha_1\cdots\alpha_m}\eta_{\beta_1'\cdots\beta_n'}^{\alpha_1'\cdots\alpha_m'};
$$
\item $\text{div}U=\mathscr D_\alpha U^\alpha$ for any vector field $U$; $\slashed{\text{div}}Y=\slashed{\nabla}_X Y^X$ and
    $\slashed{\text{div}}\kappa=\slashed\nabla^X\kappa_X$ are angular divergences for any vector field $Y$ and one-form $\kappa$ on $S_{s,u}$, respectively;
		\item If $\eta$ is a $(0,2)$-type spacetime tensor, $\Lambda$ is a 1-form, $U$ and $V$ are vector fields, then the contraction
		of $\eta$ with respect to $U$ and $V$ is defined as
		$$
		\eta_{UV}=\eta_{\alpha\beta}U^{\alpha}V^{\beta},
		$$
		and the contraction of $\Lambda$ with respect to $U$ is
		\[
		\Lambda_U=\Lambda_{\alpha}U^{\alpha};
		\]
		\item If $\eta$ is a $(0,2)$-type tensor on $S_{s,u}$, the trace of $\eta$ is defined as
		\[
		\text{tr}\eta=\slashed g^{XX}\eta_{XX}.
		\]
	\end{itemize}

In $D^{s,u}$, the Jacobian determinant of the map $(s, u, \vartheta)\rightarrow
(x^0, x^1, x^2)$ is given by
\begin{equation}\label{Jacobian}
\det\frac{\partial(x^0, x^1, x^2)}{\partial(s, u, \vartheta)}=\mu(\det\underline g)^{-1/2}\sqrt{\slashed g_{XX}}.
\end{equation}

\label{Lem3.3}
		The following identities hold:
		\begin{itemize}[leftmargin=*, labelsep=6pt, itemsep=10pt]
			\item the function $\mu$ satisfies
			\begin{equation}\label{lmu}
			\mathring{L}\mu = -\frac{1}{2}\mu G_{\mathring{L}\mathring{L}}^\gamma \mathring{L}\varphi_\gamma
			- \mu G_{\tilde{T}\mathring{L}}^\gamma \mathring{L}\varphi_\gamma + \frac{1}{2}G_{\mathring{L}\mathring{L}}^\gamma T\varphi_\gamma;
			\end{equation}
			
			\item the quantities $\zeta$ and $\sigma$ satisfy
			\begin{align}
			&\zeta_X = -\frac{1}{2}\big\{ G_{\tilde{T}\mathring{L}}^\gamma \slashed{d}_X\varphi_\gamma + G_{\tilde{T}\tilde{T}}^\gamma \slashed{d}_X\varphi_\gamma
			- G_{X\tilde{T}}^\gamma \mathring{L}\varphi_\gamma + G_{X\mathring{L}}^\gamma \tilde{T}\varphi_\gamma \big\},\label{zeta}\\
			&\sigma_{XX} = -G_{X\mathring{L}}^\gamma \slashed{d}_X\varphi_\gamma - G_{X\tilde{T}}^\gamma \slashed{d}_X\varphi_\gamma
			+ \frac{1}{2}G_{XX}^\gamma \tilde{T}\varphi_\gamma - \check{\mathscr{X}}_{XX} - \frac{\slashed{g}_{XX}}{\varrho};\label{theta}
			\end{align}
			
			\item the components of the vector fields $\mathring{L}$ and $\check{L}$ fulfill
			\begin{align}
			&\mathring{L}\mathring{L}^i = \frac{1}{2}G_{\mathring{L}\mathring{L}}^\gamma \mathring{L}\varphi_\gamma \tilde{T}^i
			- \big\{ G_{X\mathring{L}}^\gamma \mathring{L}\varphi_\gamma - \frac{1}{2}G_{\mathring{L}\mathring{L}}^\gamma \slashed{d}_X\varphi_\gamma \big\}\slashed{d}^X x^i,\label{LL}\\
			&T\check{L}^i = \big\{ \slashed{d}_X\mu - \frac{1}{2}\mu G_{\tilde{T}\tilde{T}}^\gamma \slashed{d}_X\varphi_\gamma
			- G_{X\mathring{L}}^\gamma T\varphi_\gamma \big\}\slashed{d}^X x^i + \frac{1}{2}G_{\mathring{L}\mathring{L}}^\gamma T\varphi_\gamma \tilde{T}^i \nonumber\\
			&\qquad\quad + \big\{ \frac{1}{2}\mu G_{\mathring{L}\mathring{L}}^\gamma \mathring{L}\varphi_\gamma + \mu G_{\tilde{T}\mathring{L}}^\gamma \mathring{L}\varphi_\gamma
			+ \frac{1}{2}\mu G_{\tilde{T}\tilde{T}}^\gamma \mathring{L}\varphi_\gamma \big\}\mathring{L}^i-\frac{\mu-1}{\varrho}\tilde T^i-\frac{1}{\varrho}\check T^i,\label{TL}\\
			&\mathring{L}\left( \varrho\check{L}^i \right) = \varrho\mathring{L}\mathring{L}^i,\label{LeL}\\
			&\slashed{d}_X\check{L}^i = \operatorname{tr}\check{\mathscr{X}} \slashed{d}_X x^i - \big\{ G_{\mathring{L}\tilde{T}}^\gamma \slashed{d}_X\varphi_\gamma
			+ \frac{1}{2}G_{\tilde{T}\tilde{T}}^\gamma \slashed{d}_X\varphi_\gamma \big\}\tilde{T}^i;\label{deL}
			\end{align}
			
			\item the covariant derivatives of the vector fields $\{T, \mathring{L}, X\}$ are given by
			\begin{equation}\label{cdf}
			\begin{split}
			&\mathscr{D}_{\mathring{L}}\mathring{L} = (\mu^{-1}\mathring{L}\mu)\mathring{L}, \quad
			\mathscr{D}_{T}\mathring{L} = -\mathring{L}\mu\mathring{L} + \xi^X X, \quad
			\mathscr{D}_X\mathring{L} = -\zeta_X\mathring{L} + \operatorname{tr}\chi \, X,\\
			&\mathscr{D}_{\mathring{L}}T = -\mathring{L}\mu\mathring{L} - \mu\zeta^X X, \quad
			\mathscr{D}_T T = \mu\mathring{L}\mu\mathring{L} + (\mu^{-1}T\mu + \mathring{L}\mu)T - \mu(\slashed{d}^X\mu) X,\\
			&\mathscr{D}_X T = \mu\zeta_X\mathring{L} + \mu^{-1}\xi_X T + \mu\operatorname{tr}\sigma \, X,\\
			&\mathscr{D}_X X = \slashed{\nabla}_X X + (\sigma_{XX} + \chi_{XX})\mathring{L} + \mu^{-1}\chi_{XX} T;
			\end{split}
			\end{equation}
			
			\item the covariant derivatives of the vector fields $\{\mathring{\underline{L}}, \mathring{L}, X\}$ are
			\begin{equation}\label{LuL}
			\begin{split}
			&\mathscr{D}_{\mathring{\underline{L}}}\mathring{L} = -\mathring{L}\mu\mathring{L} + 2\xi^X X, \quad
			\mathscr{D}_{\mathring{L}}\mathring{\underline{L}} = -2\mu\zeta^X X,\\
			&\mathscr{D}_{\mathring{\underline{L}}}\mathring{\underline{L}} = (\mu^{-1}\mathring{\underline{L}}\mu + \mathring{L}\mu)\mathring{\underline{L}} - (2\mu \slashed{d}^X\mu) X.
			\end{split}
			\end{equation}
		\end{itemize}

The deformation tensors corresponding to different vector fields $V$ are given as follows:
\begin{itemize}\label{lem3.4}
	\item For $V = T$,
	\begin{equation}\label{Lpi}
	\begin{split}
	&\leftidx{^{(T)}}{\pi}_{\mathring{L}\mathring{L}} = 0,
	\quad \leftidx{^{(T)}}{\pi}_{T\tilde{T}} = 2T\mu,
	\quad \leftidx{^{(T)}}{\pi}_{\mathring{L}T} = -T\mu,
	\quad \leftidx{^{(T)}}{\slashed{\pi}}_{TX} = 0, \\
	&\leftidx{^{(T)}}{\slashed{\pi}}_{\mathring{L}X} = -2\mu\zeta_X - \slashed{d}_X\mu,
	\quad \leftidx{^{(T)}}{\slashed{\pi}}_{XX} = 2\mu\sigma_{XX};
	\end{split}
	\end{equation}
	
	\item For $V = \mathring{L}$,
	\begin{equation}\label{uLpi}
	\begin{split}
	&\leftidx{^{(\mathring{L})}}{\pi}_{\mathring{L}\mathring{L}} = 0,
	\quad \leftidx{^{(\mathring{L})}}{\pi}_{T\tilde{T}} = 2\mathring{L}\mu,
	\quad \leftidx{^{(\mathring{L})}}{\pi}_{\mathring{L}T} = -\mathring{L}\mu,
	\quad \leftidx{^{(\mathring{L})}}{\slashed{\pi}}_{\mathring{L}X} = 0, \\
	&\leftidx{^{(\mathring L)}}{\slashed\pi}_{TX}=2\mu\zeta_X+\slashed d_X\mu,
	\quad \leftidx{^{(\mathring{L})}}{\slashed{\pi}}_{XX} = 2\chi_{XX};
	\end{split}
	\end{equation}
	
	\item For $V = R$,
	\begin{equation}\label{Rpi}
	\begin{split}
	&\leftidx{^{(R)}}{\pi}_{\mathring{L}\mathring{L}} = 0,
	\quad \leftidx{^{(R)}}{\pi}_{T\tilde{T}} = 2R\mu,
	\quad \leftidx{^{(R)}}{\pi}_{\mathring{L}T} = -R\mu, \\
	&\leftidx{^{(R)}}{\slashed{\pi}}_{\mathring{L}X} = -{R}^X\check{\mathscr{X}}_{XX}
	-\upsilon\big\{G_{\mathring{L}\tilde{T}}^\gamma\slashed{d}_X\varphi_\gamma
	+ \frac{1}{2}G_{\tilde{T}\tilde{T}}^\gamma\slashed{d}_X\varphi_\gamma
	- G_{X\tilde{T}}^\gamma{\mathring{L}}\varphi_\gamma\big\}
	+ \epsilon_i^jg_{ja}\check{L}^i\slashed{d}_Xx^a, \\
	&\leftidx{^{(R)}}{\slashed{\pi}}_{TX} = \mu{R}^X\check{\mathscr{X}}_{XX}
	+ \upsilon\slashed{d}_X\mu
	+ \mu G_{X\mathring{L}}^\gamma R\varphi_{\gamma}
	+ \upsilon\big\{G_{X\tilde{T}}^\gamma T\varphi_\gamma
	- \frac{1}{2}\mu G_{\tilde{T}\tilde{T}}^\gamma\slashed{d}_X\varphi_{\gamma}\big\} \\
	&\qquad\qquad + \mu G_{X\tilde{T}}^\gamma R\varphi_{\gamma}
	+ \mu\epsilon_i^j g_{ja}\check{T}^i\slashed{d}_Xx^a, \\
	&\leftidx{^{(R)}}{\slashed{\pi}}_{XX} = 2\upsilon\big(\check{\mathscr{X}}_{XX}
	+ \frac{\slashed{g}_{XX}}{\varrho}\big)
	+ 2\upsilon\big\{G_{X\mathring{L}}^\gamma\slashed{d}_X\varphi_{\gamma}
	+ G_{X\tilde{T}}^\gamma\slashed{d}_X\varphi_{\gamma}\big\}
	+ G_{XX}^\gamma R\varphi_{\gamma} \\
	&\qquad\qquad + 2\epsilon_i^j\check{g}_{ja}(\slashed{d}_Xx^a)\slashed{d}_Xx^i,
