\label{Prop.5.1}
Under the bootstrap assumptions \eqref{bootstrap-assumptions},
for small $\delta>0$ and
$t_0\le s<T_\delta$, one has
\begin{equation}\label{mathM}
\mu(s,u,\vartheta)
=
1-\frac{2\mathscr M(t_0,u,\vartheta)}{k-1}
\big(
\varrho^{-(k-1)/2}
-\varrho_0^{-(k-1)/2}
\big)
+O(\delta^{1-\varepsilon_0}),
\end{equation}
where $\varrho=s-u$ and $\varrho_0=t_0-u$.
Furthermore, at any point where $\mu(s,u,\vartheta)<1/10$,
\begin{equation}\label{blowup}
\mathring L\mu(s,u,\vartheta)
=
\varrho^{-(k+1)/2}\mathscr M(s,u,\vartheta)
+O(\delta^{1-\varepsilon_0-\varepsilon_k})
\sim -\delta^{-\varepsilon_k}.
\end{equation}

It follows from \cite[(2.36)]{Ding4} that
\begin{equation}\label{kgh}
G_{\mathring L\mathring L}^{\gamma}
\mathring L_\gamma=-kg^{\alpha\beta,\gamma\gamma_2\cdots\gamma_k}\varphi_{\gamma_2}\cdots\varphi_{\gamma_k}\mathring L_\alpha\mathring L_\beta\mathring L_\gamma-(\partial_{\varphi_\gamma}h^{\alpha\beta})\mathring L_\alpha\mathring L_\beta\mathring L_\gamma.
\end{equation}
Substituting
$h^{\alpha\beta}(\partial\phi)
=h^{\alpha\beta,\gamma_1\cdots\gamma_{k+1}}
\partial_{\gamma_1}\phi\cdots
\partial_{\gamma_{k+1}}\phi
+O(|\partial\phi|^{k+2})$
into \eqref{kgh} and using
the null condition \eqref{null} give
\begin{equation}\label{hLLL}
\begin{split}
G_{\mathring L\mathring L}^{\gamma}
\mathring L_\gamma
={}&
-(-1)^k(k+1)
h^{\alpha\beta,\gamma_1\cdots\gamma_{k+1}}
\omega_\alpha\omega_\beta
\omega_{\gamma_1}\cdots\omega_{\gamma_{k+1}}
\bigl(\tilde T^i\varphi_i\bigr)^k +O(\delta^{(k+1)(1-\varepsilon_0)}).
\end{split}
\end{equation}
By the identities $\tilde T^i\varphi_i
=
-g^{0i}\varphi_i-\mathring L\phi+\varphi_0$
and $\tilde T^iT\varphi_i=-g^{0i}T\varphi_i-\mu\tilde T^i\mathring L\varphi_i+T\varphi_0$,
together with \eqref{GT}, \eqref{hLLL} and the improved
estimates from Section~\ref{Section 3}, one has
\begin{equation}\label{GTh}
\begin{split}
G_{\mathring L\mathring L}^{\gamma}T\varphi_\gamma
={}&
(-1)^k(k+1)
h^{\alpha\beta,\gamma_1\cdots\gamma_{k+1}}
\omega_\alpha\omega_\beta
\omega_{\gamma_1}\cdots\omega_{\gamma_{k+1}}
\varphi_0^kT\varphi_0
+O(\delta^{1-\varepsilon_0-\varepsilon_k}).
\end{split}
\end{equation}
Hence, by \eqref{lmu} and \eqref{GTh}, we arrive at
\begin{equation}\label{rLmu}
\varrho^{(k+1)/2}\mathring L\mu(s,u,\vartheta)
=
\mathscr M(s,u,\vartheta)
+O(\delta^{1-\varepsilon_0-\varepsilon_k}),
\end{equation}
which proves the identity in \eqref{blowup}.

In addition,
the identity $\mathring L\omega_i
=\frac{\check L^i}{r}
-\frac{x^ix^j\check L^j}{r^3}$
and the bound for $\check L$ imply
\[
	\omega_i(s,u,\vartheta)=\omega_i(t_0,u,\vartheta)+\int_{t_0}^s\mathring L\omega_i(\tau,u,\vartheta)d\tau =\omega_i(t_0,u,\vartheta)+O(\delta^{\varepsilon_0}).
	\]
	This, together with \eqref{Tvp}, \eqref{r0vp} and \eqref{rLmu}, yields
	\begin{equation}\label{rhoLmu}
	\varrho^{(k+1)/2}\mathring{L}\mu(s, u, \vartheta) = \mathscr M(t_0, u, \vartheta)+O(\delta^{1-\varepsilon_0-\varepsilon_k}).
	\end{equation}
Therefore,
	\begin{equation*}
	\begin{split}
	\mu(s,u,\vartheta)
	&= \mu(t_0,u,\vartheta)
	+ \int_{t_0}^s \frac{\varrho^{(k+1)/2}\mathring{L}\mu(\tau,u,\vartheta)}{\varrho^{(k+1)/2}}d\tau \\
	&= \mu(t_0,u,\vartheta)
	- \frac{2\mathscr{M}(t_0,u,\vartheta)}{k-1}\big(\varrho^{-(k-1)/2} - \varrho_0^{-(k-1)/2}\big)
	+ O(\delta^{1-\varepsilon_0}),
	\end{split}
	\end{equation*}
	which proves \eqref{mathM}.

Suppose now that $\mu(s,u,\vartheta)<1/10$.
Retaining the error term in \eqref{mathM}, we obtain that
for small $\delta$,
\[
\mathscr{M}(t_0,u,\vartheta) \leq \frac{9(k-1)}{20\big(\varrho^{-(k-1)/2} - \varrho_0^{-(k-1)/2}\big)}.
\]
Therefore, using \eqref{rhoLmu} again yields
\begin{equation*}
\begin{split}
\varrho^{(k+1)/2}\mathring{L}\mu(s,u,\vartheta)
&\leq \frac{-9}{10\int_{t_0}^s (\tau-u)^{-(k+1)/2}d\tau} + O\left(\delta^{1-\varepsilon_0-\varepsilon_k}\right) \\
&= \frac{-9(\tilde\tau-u)^{(k+1)/2}}{10(s-t_0)} + O\left(\delta^{1-\varepsilon_0-\varepsilon_k}\right)
\lesssim -\delta^{\varepsilon_k},
\end{split}
\end{equation*}
where $\tilde\tau \in (t_0,s)$ and $\tilde\tau - u \sim 1$. On the other hand, it follows from \eqref{eq:higher-order-L-infty-estimates} that $|\mathring{L}\mu(s,u,\vartheta)| \lesssim \delta^{-\varepsilon_k}$, so \eqref{blowup} holds.

\label{lem:higher_order_L2_estimates_mu}
Under the assumptions of Proposition~\ref{Prop.5.1}, let $E=
\left\{
\tau\in[t_0,T_\delta):
\mu_{\min}(\tau)<\frac{1}{10}
\right\}$.
For small $\delta>0$, the following
statements hold.

If $E\neq\varnothing$, set $\underline s=\inf E$.
Then, for any $a>1$ and
$\underline s<s<T_\delta$,
\begin{equation}\label{eq:mu_integrability}
\int_{\underline s}^{s}\mu_{\min}^{-a}(\tau)\,d\tau
\lesssim
\frac{\delta^{\varepsilon_k}}{a-1}
\mu_{\min}^{1-a}(s).
\end{equation}

Regardless of whether $E$ is empty, for any
$s,s'\in[t_0, T_\delta)$ with $s<s'$, one has
\begin{equation}\label{eq:mu_monotonicity}
\mu_{\min}(s')\lesssim\mu_{\min}(s).
\end{equation}

We shall also use the following consequence of
\eqref{eq:mu_integrability}:

Set $\underline{\underline{s}}
=\inf\big\{\tau\geq t_0:
\mu_{\min}(\tau)<\frac{1}{100}\big\}$.
When $s\leq\underline{\underline{s}}$, one has
$\mu_{\min}(s)\geq\frac{1}{100}$ and then the negative powers of
$\mu_{\min}$ are bounded from above;
When $s>\underline{\underline{s}}$, decomposing $[t_0, s]=[t_0, \underline{s})\cup [\underline{s}, s]$ and applying
\eqref{eq:mu_integrability} on $[\underline{s},s]$, one can obtain that for
all sufficiently large $a$,
\begin{align}
\int_{t_0}^{s}\mu_{\min}^{-a}(\tau)\,d\tau
&\lesssim
10^a\delta^{\varepsilon_k}
+\frac{\delta^{\varepsilon_k}}{a-1}
\mu_{\min}^{1-a}(s) \nonumber\\
&\lesssim
\delta^{\varepsilon_k}\mu_{\min}^{1-a}(s)
\big(\frac{1}{10^{a-2}}+\frac{1}{a-1}\big) \nonumber\\
&\lesssim
\frac{\delta^{\varepsilon_k}}{a-1}
\mu_{\min}^{1-a}(s).
\label{eq:mu-integrability-full}
\end{align}

