=R^m\Omega^i
+R^m\bigl(-\upsilon g^{0i}
-\upsilon\check L^i-\upsilon\frac{x^i}{\varrho}\bigr)
\]
to derive
\[
|R^{m+1}x^i|
\lesssim 1+|R^{\leq m}\upsilon|
+\delta^{k(1-\varepsilon_0)}|R^{\leq m}\check L^i|
+\delta^{(2k-1)(1-\varepsilon_0)}|R^{\leq m}\varphi|.
\]
Thus, for any smooth function $h$, one has
\begin{equation*}
\begin{split}
\|R^{m+1}(hx^i)\|_{s,u}
\lesssim&\ \|R^{\leq m+1}h\|_{s,u}
+\|R^{\leq\lfloor m/2\rfloor}h\|_{L^\infty}
\bigl(\|R^{\leq m}\upsilon\|_{s,u}
+\delta^{k(1-\varepsilon_0)}
\|R^{\leq m}\check L^i\|_{s,u}\\
&+\delta^{(2k-1)(1-\varepsilon_0)}
\|R^{\leq m}\varphi\|_{s,u}\bigr).
\end{split}
\end{equation*}
By induction method, it follows from \eqref{RML}, \eqref{RNL} and
\eqref{RNU} that
\begin{equation}\label{RmL}
\begin{split}
\|R^{m+1}\check L^i\|_{s,u}
\lesssim&\ \delta^{k(1-\varepsilon_0)+3/2}
+\delta^{k(1-\varepsilon_0)}\|R^{\leq m}\upsilon\|_{s,u}
+\|R^{\leq m}\operatorname{tr}\check{\mathscr X}\|_{s,u}\\
&+\delta^{k(1-\varepsilon_0)+\varepsilon_0}
\sum_{j=1}^2\sqrt{\mathcal E_{j,\leq m+2}(s,u)}.
\end{split}
\end{equation}
Similarly, using \eqref{omega} and \eqref{RNU}, we have
\begin{equation}\label{RmU}
\begin{split}
\|R^{m+1}\upsilon\|_{s,u}
\lesssim&\ \delta^{k(1-\varepsilon_0)+3/2}
+\sum_{j=1}^2\|R^{\leq m+1}\check L^j\|_{s,u}
+\|R^{\leq m}\operatorname{tr}\check{\mathscr X}\|_{s,u}\\
&+\delta^{k(1-\varepsilon_0)+\varepsilon_0}
\sum_{j=1}^2\sqrt{\mathcal E_{j,\leq m+2}(s,u)}.
\end{split}
\end{equation}
It follows from \eqref{RmL}, \eqref{RmU} and the induction argument that
\begin{equation}\label{RmLU}
\begin{split}
\|R^{m+1}\check L^i\|_{s,u}
+\|R^{m+1}\upsilon\|_{s,u}
\lesssim&\ \delta^{k(1-\varepsilon_0)+3/2}
+\|R^{\leq m}\operatorname{tr}\check{\mathscr X}\|_{s,u}+\delta^{k(1-\varepsilon_0)+\varepsilon_0}
\sum_{j=1}^2\sqrt{\mathcal E_{j,\leq m+2}(s,u)}.
\end{split}
\end{equation}
By \eqref{Rpi}, \eqref{rrho} and \eqref{RmLU}, we conclude that
\begin{equation}\label{Rmrpi}
\begin{split}
\|R^{m+1}\check\varrho\|_{s,u}
+\bigl\|\slashed{\mathcal L}_R^{m}{}^{(R)}
\slashed{\pi}\bigr\|_{s,u}
\lesssim&\ \delta^{k(1-\varepsilon_0)+3/2}
+\|R^{\leq m}\operatorname{tr}\check{\mathscr X}\|_{s,u}+\delta^{k(1-\varepsilon_0)+\varepsilon_0}
\sum_{j=1}^2\sqrt{\mathcal E_{j,\leq m+2}(s,u)}
\end{split}
\end{equation}
and
\begin{equation}\label{RmpiL}
\begin{split}
&\bigl\|\slashed{\mathcal L}_R^{m}{}^{(R)}
\slashed{\pi}_{\mathring L}\bigr\|_{s,u}\\
\lesssim &
\bigl(1+\delta^{2k(1-\varepsilon_0)-\varepsilon_0}\bigr)
\bigl(\delta^{k(1-\varepsilon_0)+3/2}
+\|R^{\leq m}\operatorname{tr}\check{\mathscr X}\|_{s,u}
+\delta^{k(1-\varepsilon_0)+\varepsilon_0}
\sum_{j=1}^2\sqrt{\mathcal E_{j,\leq m+2}(s,u)}\bigr).
\end{split}
\end{equation}

Next, we estimate
$\|R^{\leq m}\operatorname{tr}\check{\mathscr X}\|_{s,u}$.
In this process, the transport equation \eqref{transport} in
Lemma~\ref{lem:null-transport} will be used.
Note that the first term on the right-hand side of \eqref{transport}
contains the factor
$G_{\mathring L\mathring L}^\gamma\mathring L_\gamma$.
By \eqref{gLLL} and
Proposition~\ref{prop:bootstrap-higher-derivatives}, we have
$\bigl|R^{\leq N-3}
\bigl(G_{\mathring L\mathring L}^\gamma\mathring L_\gamma\bigr)\bigr|
\lesssim\delta^{k(1-\varepsilon_0)}$.
Consequently,
\begin{equation}\label{RGLLLvp}
\begin{split}
&\bigl\|R^m\bigl(\varrho^2
\bigl(G_{\mathring L\mathring L}^\gamma\mathring L_\gamma\bigr)
\tilde T^i\slashed\triangle\varphi_i\bigr)\bigr\|_{s,u}\\
\lesssim&\ \delta^{k(1-\varepsilon_0)}
\bigl\{\|R^{\leq m}\slashed\triangle\varphi\|_{s,u}
+\|R^{\leq m}\upsilon\|_{s,u}
+\sum_{i=1}^2\|R^{\leq m}\check L^i\|_{s,u}\bigr\}
+\delta^{(k-1)(1-\varepsilon_0)}
\|R^{\leq m}\varphi\|_{s,u}.
\end{split}
\end{equation}
Substituting \eqref{RGLLLvp} into \eqref{transport} and using
\eqref{RmLU}--\eqref{RmpiL} yield
\begin{align*}
&\bigl\|\mathring LR^m
\bigl(\varrho^2
\bigl(\operatorname{tr}\check{\mathscr X}-E_0\bigr)\bigr)
\bigr\|_{s,u}\\
\lesssim&
\bigl\|\bigl[\mathring L,R^m\bigr]
\bigl(\varrho^2
\bigl(\operatorname{tr}\check{\mathscr X}-E_0\bigr)\bigr)
\bigr\|_{s,u}
+\bigl\|R^m\mathring L
\bigl(\varrho^2
\bigl(\operatorname{tr}\check{\mathscr X}-E_0\bigr)\bigr)
\bigr\|_{s,u}\\
\lesssim&
\delta^{k(1-\varepsilon_0)}
\bigl(\|\slashed dR^{m+1}\varphi\|_{s,u}
+\bigl\|\slashed{\mathcal L}_R^{\leq m}
\leftidx{^{(R)}}{\slashed\pi}_{\mathring L}\bigr\|_{s,u}\bigr)
+\delta^{2k(1-\varepsilon_0)-\varepsilon_0}
\bigl\|R^{\leq m}
\bigl(\varrho^2
\bigl(\operatorname{tr}\check{\mathscr X}-E_0\bigr)\bigr)
\bigr\|_{s,u}\\
&+\delta^{2k(1-\varepsilon_0)-\varepsilon_0}
\bigl\{\bigl\|\slashed{\mathcal L}_R^{\leq m}
\leftidx{^{(R)}}{\slashed\pi}\bigr\|_{s,u}
+\sum_{i=1}^2\|R^{\leq m+1}\check L^i\|_{s,u}
+\|R^{\leq m+1}\upsilon\|_{s,u}\bigr\}\\
&+\delta^{2k(1-\varepsilon_0)}
\bigl(\sqrt{\mathcal E_{1,\leq m+2}(s,u)}
+\sqrt{\mathcal E_{2,\leq m+2}(s,u)}\bigr)\\
\lesssim&
\delta^{3k(1-\varepsilon_0)-\varepsilon_0+3/2}
+\delta^{k(1-\varepsilon_0)}
\mu_{\min}^{-1/2}(s)
\sqrt{\mathcal E_{1,\leq m+2}(s,u)}
+\delta^{2k(1-\varepsilon_0)}
\sqrt{\mathcal E_{2,\leq m+2}(s,u)}\\
&+\delta^{2k(1-\varepsilon_0)-\varepsilon_0}
\bigl\|R^{\leq m}
\bigl(\varrho^2
\bigl(\operatorname{tr}\check{\mathscr X}-E_0\bigr)\bigr)
\bigr\|_{s,u}.
\end{align*}
Summing the above inequalities over the derivative orders up to $m$,
using the initial data estimates and \eqref{Ff}, and applying Gronwall's
inequality, we can obtain \eqref{RmXE}.
In addition, by the definition of $E_0$,
$\|R^{\leq m}E_0\|_{s,u}$ may be estimated. This, together with
\eqref{RmLU} and \eqref{Rmrpi}, yields \eqref{RmcX}.
Finally, \eqref{RmPiL} follows from \eqref{RmpiL}.

\label{YHC-A3}
Under the assumptions of Proposition~\ref{EstimatesOnR},
for any $s$ with $t_0\leq s<T_\delta$ and $u\in[0,4\delta]$,
the following estimates hold:
\begin{equation}\label{RMMu}
\begin{split}
\|R^{m+1}\mu\|_{s,u}
\lesssim{}&
\delta^{k(1-\varepsilon_0)+\varepsilon_0-1/2}
+\delta^{(k-1)(1-\varepsilon_0)}\Xi^2_{m+2}(s,u)
\end{split}
\end{equation}
and
\begin{equation}\label{RMPIRT}
\begin{split}
\|\slashed{\mathcal L}_R^m{}^{(R)}\slashed\pi_T\|_{s,u}
\lesssim{}&
\delta^{2k(1-\varepsilon_0)-1/2}
+\delta^{2k(1-\varepsilon_0)-1}\Xi_{m+2}^1(s,u),
\end{split}
\end{equation}
where $\Xi_{m+2}^1(s,u)$ is defined in
Proposition~\ref{EstimatesOnR} and
\[
\Xi_{m+2}^2(s,u)
=\int_{t_0}^s
\bigl\{\mu_{\min}^{-1/2}(\tau)
\sqrt{\mathcal E_{1,\leq m+2}(\tau,u)}
+\sqrt{\mathcal E_{2,\leq m+2}(\tau,u)}\bigr\}\,d\tau.
\]

Note that even without the null condition \eqref{null}, one still has
\[
|G_{\mathring L\mathring L}^\gamma T\varphi_\gamma|
\lesssim |\varphi|^{k-1}|T\varphi|.
\]
This, together with the estimate of
$[\mathring L,R^{m+1}]\mu$ and \eqref{lmu}, yields
\begin{equation}\label{RMmu}
\begin{split}
\|\mathring L R^{m+1}\mu\|_{s,u}
\lesssim{}&
\delta^{2k(1-\varepsilon_0)-\varepsilon_0}
\|R^{\leq m+1}\mu\|_{s,u}
+\delta^{(k-1)(1-\varepsilon_0)-1}
\|R^{\leq m+1}\varphi\|_{s,u}\\
&+\delta^{(k-1)(1-\varepsilon_0)}
\bigl(\|R^{\leq m+1}T\varphi\|_{s,u}
+\|\mu R^{m+1}\mathring L\varphi\|_{s,u}
+\|R^{\leq m}\mathring L\varphi\|_{s,u}\bigr)\\
&+\delta^{k(1-\varepsilon_0)-1}
\bigl(\sum_{i=1}^2\|R^{\leq m+1}\check L^i\|_{s,u}
+\|R^{\leq m+1}\upsilon\|_{s,u}\bigr)
+\|\slashed{\mathcal L}_R^m{}^{(R)}
\slashed\pi_{\mathring L}\|_{s,u}.
\end{split}
\end{equation}
In addition, we have
\begin{equation}\label{YHC-A2}
\begin{split}
R^{\leq m+1}T\varphi
&=TR^{\leq m+1}\varphi+[R^{\leq m+1},T]\varphi,\\
\mu R^{m+1}\mathring L\varphi
&=\mu\mathring L R^{m+1}\varphi
+\mu[R^{m+1},\mathring L]\varphi.
\end{split}
\end{equation}
It follows from \eqref{Rpi}, \eqref{YHC-A2}, \eqref{RmLU} and the estimates
in Proposition~\ref{EstimatesOnR} that
\begin{equation}\label{DXY-7}
\begin{split}
\|\slashed{\mathcal L}_R^m{}^{(R)}\slashed\pi_T\|_{s,u}
\lesssim{}&
\|R^{\leq m}\operatorname{tr}\check{\mathscr X}\|_{s,u}
+\delta^{k(1-\varepsilon_0)}\|R^{\leq m+1}\mu\|_{s,u}
+\delta^{k(1-\varepsilon_0)-1}\|R^{\leq m}\upsilon\|_{s,u}\\
&+\delta^{(2k-1)(1-\varepsilon_0)-1}
\|R^{\leq m+1}\varphi\|_{s,u}
+\delta^{(2k-1)(1-\varepsilon_0)}
\|R^{\leq m}T\varphi\|_{s,u}\\
&+\bigl(1+\delta^{2k(1-\varepsilon_0)-1}\bigr)
\sum_{i=1}^2\|R^{\leq m}\check L^i\|_{s,u}\\
\lesssim{}&
\delta^{2k(1-\varepsilon_0)-1/2}
+\delta^{2k(1-\varepsilon_0)-1}\Xi_{m+2}^1(s,u)
+\delta^{k(1-\varepsilon_0)}
\|R^{\leq m+1}\mu\|_{s,u}\\
&+\delta^{(2k-1)(1-\varepsilon_0)}
\sum_{i=1}^2\sqrt{\mathcal E_{i,\leq m+2}(s,u)}.
\end{split}
\end{equation}
Substituting \eqref{YHC-A2} into \eqref{RMmu}, using
Proposition~\ref{EstimatesOnR}, and applying \eqref{SiSi}
to treat $\|R^{\leq m}\mathring L\varphi\|_{s,u}$, we arrive at
\[
\begin{split}
\|\mathring L R^{m+1}\mu\|_{s,u}
\lesssim{}&
\delta^{2k(1-\varepsilon_0)-1/2}
+\delta^{2k(1-\varepsilon_0)-1}\Xi_{m+2}^1(s,u)
+\delta^{2k(1-\varepsilon_0)-\varepsilon_0}
\|R^{\leq m+1}\mu\|_{s,u}\\
&+\delta^{(k-1)(1-\varepsilon_0)}
\sum_{i=1}^2\sqrt{\mathcal E_{i,\leq m+2}(s,u)}.
\end{split}
\]
By
$\mu|_{t_0}
=\frac{1}{\sqrt{(g^{0i}\omega_i)^2+g_{ij}\omega_i\omega_j}}$
and the initial data estimates, it holds that
$$\|R^{m+1}\mu\|_{t_0,u}
\lesssim\delta^{k(1-\varepsilon_0)+1/2}.$$
Therefore, applying the above estimates up to $(m+1)-$order derivatives, the uniform
bound of $\mu$, \eqref{Ff}, the definitions of
$\Xi_{m+2}^1$ and $\Xi_{m+2}^2$ and Gronwall's inequality,
\eqref{RMMu} can be achieved.

Finally, substituting \eqref{RMMu} into \eqref{DXY-7} yields \eqref{RMPIRT}.

\label{Cor6.2}
Under the assumptions of Proposition~\ref{EstimatesOnR},
the following estimate holds for sufficiently large $b_{m+2}$:
\begin{equation}\label{cortop}
\begin{split}
&\delta^{\varepsilon_k}
\bigl|\int_{\Sigma_s^u}
(R^m\operatorname{tr}\check{\mathscr X})
\mathring{\underline L}\varphi_\gamma
(R^{m+2}\varphi_\gamma)\bigr|\\
\lesssim{}&
\delta^{2-2\varepsilon_0}
\mu_{\min}^{-2b_{m+2}}(s)b_{m+2}
+\delta^{-(k+1)(1-\varepsilon_0)}
\int_0^u\mathcal F_{1,\leq m+2}(s,u')\,du'\\
&+\frac{\mu_{\min}^{-2b_{m+2}}(s)}{b_{m+2}}
\bigl(
\delta^{\varepsilon_k}
\widetilde{\mathcal E}_{1,\leq m+2}(s,u)
+\delta\widetilde{\mathcal E}_{2,\leq m+2}(s,u)
\bigr).
\end{split}
\end{equation}

By the definition of $E_0$ in
Lemma~\ref{lem:null-transport}, decompose the integral
on the left-hand side of \eqref{cortop} as
\begin{equation}\label{I+II}
\delta^{\varepsilon_k}
\int_{\Sigma_s^u}
(R^m\operatorname{tr}\check{\mathscr X})
\mathring{\underline L}\varphi_\gamma
(R^{m+2}\varphi_\gamma)
=I+II,
\end{equation}
where
\begin{align*}
I&=\delta^{\varepsilon_k}
\int_{\Sigma_s^u}
\bigl(R^m(\operatorname{tr}\check{\mathscr X}-E_0)\bigr)
\mathring{\underline L}\varphi_\gamma
(R^{m+2}\varphi_\gamma),\\
II&=\delta^{\varepsilon_k}
\int_{\Sigma_s^u}
(R^mE_0)\mathring{\underline L}\varphi_\gamma
(R^{m+2}\varphi_\gamma).
\end{align*}
Invoking the identity \cite[(10.1a)]{Sp},
we rewrite the term $II$ as
\begin{equation*}
\begin{split}
II={}&\delta^{\varepsilon_k}
\int_{\Sigma_{t_0}^u}
(R^mE_0)\mathring{\underline L}\varphi_\gamma
(R^{m+2}\varphi_\gamma)+\delta^{\varepsilon_k}
\int_{D^{s,u}}(\mathring L+\operatorname{tr}\chi)
\bigl(
(R^mE_0)\mathring{\underline L}\varphi_\gamma
(R^{m+2}\varphi_\gamma)
\bigr).
\end{split}
\end{equation*}
Then
\begin{equation}\label{YHC-A4}
\begin{split}
|II|\lesssim{}&
\delta^{2-\varepsilon_0}
+\delta^{\varepsilon_k}
\bigl|\int_{D^{s,u}}
(\mathring LR^mE_0)\mathring{\underline L}\varphi_\gamma
(R^{m+2}\varphi_\gamma)\bigr|+\delta^{\varepsilon_k}
\bigl|\int_{D^{s,u}}
(R^mE_0)\mathring L\mathring{\underline L}\varphi_\gamma
(R^{m+2}\varphi_\gamma)\bigr|\\
&+\delta^{\varepsilon_k}
\bigl(1+\delta^{2k(1-\varepsilon_0)-\varepsilon_0}\bigr)
\int_{D^{s,u}}
\bigl|
(R^mE_0)\mathring{\underline L}\varphi_\gamma
(R^{m+2}\varphi_\gamma)
\bigr|\\
&+\delta^{\varepsilon_k}
\bigl|\int_{D^{s,u}}
(R^mE_0)\mathring{\underline L}\varphi_\gamma
(\mathring LR^{m+2}\varphi_\gamma)\bigr|.
\end{split}
\end{equation}
Note that
\begin{equation*}
\begin{split}
&\int_{D^{s,u}}
(R^mE_0)\mathring{\underline L}\varphi_\gamma
(\mathring LR^{m+2}\varphi_\gamma)=\int_{D^{s,u}}
(R^mE_0)\mathring{\underline L}\varphi_\gamma
(\slashed d_XR^{m+1}\varphi_\gamma)
{}^{(R)}\slashed{\pi}_{\mathring L}^X\\
&\qquad-\int_{D^{s,u}}
R\bigl((R^mE_0)\mathring{\underline L}\varphi_\gamma\bigr)
(\mathring LR^{m+1}\varphi_\gamma)-\int_{D^{s,u}}
\tfrac12(R^mE_0)\mathring{\underline L}\varphi_\gamma
(\mathring LR^{m+1}\varphi_\gamma)
\operatorname{tr}{}^{(R)}\slashed{\pi}.
\end{split}
\end{equation*}
Substituting this into \eqref{YHC-A4} yields
\begin{equation*}
\begin{split}
|II|\lesssim{}&
\delta^{2-\varepsilon_0}
+\delta^{\varepsilon_0-1}
\int_{D^{s,u}}
|\mathring LR^{\leq m+1}\varphi|
\Bigl(
|\slashed dR^{m+1}\varphi|
+\delta^{1-\varepsilon_0}
\bigl(
\sum_{i=1}^2|R^{\leq m+1}\check L^i|
+|R^{\leq m+1}\upsilon|
\bigr)
\Bigr)\\
&+\delta^{k(1-\varepsilon_0)-1}
\int_{D^{s,u}}
\bigl(
|R^{\leq m+1}\varphi|
+\delta^{\varepsilon_0}|R^{\leq m}\mathring L\varphi|
\bigr)|R^{m+2}\varphi|\\
&+\int_{D^{s,u}}
\Bigl(
|\slashed{\mathcal L}_R^{\leq m}
{}^{(R)}\slashed{\pi}_{\mathring L}|
+\delta^{-\varepsilon_k}
\bigl(
\sum_{i=1}^2|R^{\leq m+1}\check L^i|
+|R^{\leq m+1}\upsilon|
\bigr)
\Bigr)|R^{m+2}\varphi|.
\end{split}
\end{equation*}
Together with the estimates in
Proposition~\ref{EstimatesOnR}, we further deduce
\begin{align}
|II|\lesssim{}&
\delta^{2-\varepsilon_0}
+\delta^{-(k+1)(1-\varepsilon_0)}
\int_0^u\mathcal F_{1,\leq m+2}(s,u')\,du'
+\delta^{(3k+2)(1-\varepsilon_0)-\varepsilon_0}
\int_{t_0}^s\mu_{\min}^{-2b_{m+2}}(\tau)\,d\tau
\nonumber\\
&+\delta^{(k-1)(1-\varepsilon_0)}
\int_{t_0}^s
\mu_{\min}^{-1-2b_{m+2}}(\tau)
\widetilde{\mathcal E}_{1,\leq m+2}(\tau,u)\,d\tau
\nonumber\\
&+\delta^{(k+1)(1-\varepsilon_0)}
\int_{t_0}^s
\mu_{\min}^{-2b_{m+2}}(\tau)
\widetilde{\mathcal E}_{2,\leq m+2}(\tau,u)\,d\tau
\nonumber\\
\lesssim{}&
\delta^{2-2\varepsilon_0}
\mu_{\min}^{-2b_{m+2}}(s)
+\delta^{-(k+1)(1-\varepsilon_0)}
\int_0^u\mathcal F_{1,\leq m+2}(s,u')\,du'
\label{II}\\
&+\frac{\mu_{\min}^{-2b_{m+2}}(s)}{b_{m+2}}
\bigl(
\delta^{2\varepsilon_0-1}
\widetilde{\mathcal E}_{1,\leq m+2}(s,u)
+\delta\widetilde{\mathcal E}_{2,\leq m+2}(s,u)
\bigr),
\nonumber
\end{align}
where \eqref{eq:mu-integrability-full} is used and
$b_{m+2}$ is chosen to be sufficiently large.

For the term $I$, it follows from \eqref{RmXE} that
\begin{align}
|I|\lesssim{}&
\delta^{-k(1-\varepsilon_0)}
\|R^m(\operatorname{tr}\check{\mathscr X}-E_0)\|_{s,u}
\|\slashed dR^{m+1}\varphi\|_{s,u}
\nonumber\\
\lesssim{}&
\Bigl\{
\delta^{1/2}
+\frac{\delta^{\varepsilon_k}}{b_{m+2}}
\mu_{\min}^{-b_{m+2}+1/2}(s)
\sqrt{\widetilde{\mathcal E}_{1,\leq m+2}(s,u)}
\nonumber\\
&\qquad
+\frac{\delta^{\varepsilon_0}}{b_{m+2}}
\mu_{\min}^{1-b_{m+2}}(s)
\sqrt{\widetilde{\mathcal E}_{2,\leq m+2}(s,u)}
\Bigr\}
\mu_{\min}^{-b_{m+2}-1/2}(s)
\sqrt{\widetilde{\mathcal E}_{1,\leq m+2}(s,u)}
\nonumber\\
\lesssim{}&
\delta^{(k+1)(1-\varepsilon_0)}
b_{m+2}\mu_{\min}^{-1}(s)
+\frac{\mu_{\min}^{-2b_{m+2}}(s)}{b_{m+2}}
\Bigl(
\delta^{\varepsilon_k}
\widetilde{\mathcal E}_{1,\leq m+2}(s,u)
\nonumber\\
&\hspace{7cm}
+\delta^{\varepsilon_0+k(1-\varepsilon_0)}
\widetilde{\mathcal E}_{2,\leq m+2}(s,u)
\Bigr).
\label{I}
\end{align}
Combining \eqref{II} and \eqref{I} with \eqref{I+II}
yields \eqref{cortop}.

\label{L2chi}
	Under the assumptions \eqref{bootstrap-assumptions}, for all \(0\leq m\leq 2N-6\) and small \(\delta>0\), the following estimates hold:
	\begin{align*}
		&\delta^{l+p\varepsilon_k}\bigl(\|Z^m\operatorname{tr}\check{\mathscr X}\|_{s,u}+\|Z^{m+1}\check L^i\|_{s,u}+\|Z^{m+1}\upsilon\|_{s,u}+\|Z^{m+1}\check\varrho\|_{s,u}+\bigl\|\slashed{\mathcal L}_Z^{m}{}^{(R)}\slashed{\pi}\bigr\|_{s,u}\bigr)\\
		&\qquad\qquad\lesssim\ \delta^{k(1-\varepsilon_0)+1/2}+\delta^{k(1-\varepsilon_0)}\Xi^1_{m+2}(s,u),\\
		&\delta^{l+p\varepsilon_k}\|Z^{m+2}x^i\|_{s,u}\lesssim\delta^{1/2}+\delta^{k(1-\varepsilon_0)}\Xi^1_{m+2}(s,u),\\
		&\delta^{l+p\varepsilon_k}\|\slashed{\mathcal L}_Z^{m+1}\slashed g\|_{s,u}\lesssim\delta^{k(1-\varepsilon_0)}\bigl(\delta^{1/2}\bigl(1+\delta^{\varepsilon_0-2k(1-\varepsilon_0)}\bigr)+\Xi^1_{m+2}(s,u)\bigr),\\
		&\delta^{l+p\varepsilon_k}\|\slashed{\mathcal L}_Z^{m}{}^{(R)}\slashed{\pi}_{\mathring L}\|_{s,u}\lesssim\delta^{k(1-\varepsilon_0)}\bigl(1+\delta^{2k(1-\varepsilon_0)-\varepsilon_0}\bigr)\bigl(\delta^{1/2}+\Xi_{m+2}^1(s,u)\bigr),\\
		&\delta^{l+p\varepsilon_k}\|\slashed{\mathcal L}_Z^{m+1}R\|_{s,u}\lesssim \delta^{\varepsilon_0}\bigl(1+\delta^{2k(1-\varepsilon_0)-\varepsilon_0}\bigr)\bigl(\delta^{1/2}+\Xi_{m+2}^1(s,u)\bigr),\\
		&\delta^{l+p\varepsilon_k}\|\slashed{\mathcal L}_Z^m{}^{(R)}\slashed\pi_T\|_{s,u}
		\lesssim  \delta^{2k(1-\varepsilon_0)-1/2} + \delta^{2k(1-\varepsilon_0)-1}\Xi^1_{m+2}(s,u),\\
		&\delta^{l+p\varepsilon_k}\|Z^{m+1}\mu\|_{s,u} \lesssim \delta^{k(1-\varepsilon_0)+\varepsilon_0-1/2} + \delta^{(k-1)(1-\varepsilon_0)}\Xi^2_{m+2}(s,u)+\delta^{2\varepsilon_0-1}\sum_{i=1}^2\sqrt{\mathcal E_{i,\leq m+2}(s,u)}
	\end{align*}
	and
	\begin{equation*}
		\begin{split}
			&\delta^{l+p\varepsilon_k}\bigl(\|\slashed{\mathcal L}_Z^m{}^{(T)}\slashed\pi_{\mathring L}\|_{s,u}+\|\slashed{\mathcal L}_Z^m{}^{(T)}\slashed\pi\|_{s,u}\bigr)\\
			\lesssim &\delta^{k(1-\varepsilon_0)-1/2} + \delta^{2k(1-\varepsilon_0)-1}\int_{t_0}^s\mu_{\min}^{-1/2}(\tau)\sqrt{\mathcal E_{1,\leq m+2}(\tau,u)}\,d\tau \\
			&+\delta^{(k-1)(1-\varepsilon_0)}\bigl(\bigl(1+\delta^{2k(1-\varepsilon_0)-\varepsilon_0}\bigr)\int_{t_0}^s\sqrt{\mathcal E_{2,\leq m+2}(\tau,u)}\,d\tau+ \sum_{i=1}^2\sqrt{\mathcal E_{i,\leq m+2}(s,u)}\bigr),
		\end{split}
	\end{equation*}
	where \(l\) and \(p\) denote the numbers of \(T\) and \(\varrho\mathring L\) in the corresponding derivative strings, respectively.

By Lemma~\ref{Lem3.3}, the quantities \(\varrho\mathring{L}\check{L}^i\), \(T\check{L}^i\) and \(R\check{L}^i\) can be expressed as
\[
\varrho\mathring{L}\check{L}^i = \varrho\mathring{L}\mathring{L}^i - \check{L}^i,
\quad
T\check{L}^i = T\mathring{L}^i + \frac{\mu}{\varrho}g^{0i} + \frac{\mu}{\varrho}\check{L}^i + \frac{\mu-1}{\varrho^2}y^i,
\quad
R\check{L}^i = {R^X}\slashed{d}_X\check{L}^i.
\]
Then we have
\begin{equation}\label{ZkL}
\begin{split}
&\delta^{l+p\varepsilon_k} \| Z^{m+1}\check{L}^i \|_{s,u} \\
\lesssim&\delta^{1/2} \bigl( \delta^{2k(1-\varepsilon_0)} + \delta^{\varepsilon_0} \bigr)
+ \delta^{l_1+p_1\varepsilon_k} \| Z^{m_1} \operatorname{tr}\check{\mathscr{X}} \|_{s,u} + \delta^{k(1-\varepsilon_0)} \delta^{l_0+p_0\varepsilon_k} \| Z^{m_0}x \|_{s,u}\\
&+ \delta(1+\delta^{2k(1-\varepsilon_0)-\varepsilon_0}) \delta^{l_0+p_0\varepsilon_k} \| Z^{m_0}\mu \|_{s,u} + \delta^{k(1-\varepsilon_0)} \delta^{l_1+p_1\varepsilon_k} \| \slashed{\mathcal L}_Z^{m_1}\slashed{g} \|_{s,u} \\
&+ \delta^{k(1-\varepsilon_0)+\varepsilon_0} \bigl( \sqrt{\mathcal E_{1,\leq m+2}(s,u)} + \sqrt{\mathcal E_{2,\leq m+2}(s,u)} \bigr),
\end{split}
\end{equation}
where the bound \(\|1\|_{s,u}\lesssim\delta^{1/2}\) is used. Here \(l\) and \(p\) (resp.\ \(l_n\) and \(p_n\), \(n=0,1\)) denote the numbers of \(T\) and \(\varrho\mathring{L}\) in the string \(Z^{m+1}\) (resp.\ \(Z^{m_n}\)) with \(0 \leq m_n \leq m+1-n\).

Similarly, from the identities \(\varrho\mathring Lx^i=\varrho\check L^i+x^i\), \(Tx^i=\mu(-g^{0i}-\check L^i-\frac{x^i}{\varrho})\) and \(Rx^i=\Omega^i+\upsilon(g^{0i}+\check L^i+\frac{x^i}{\varrho})\), one has
\begin{equation}\label{Zkx}
\begin{split}
&\delta^{l+p\varepsilon_k}\|Z^{m+2}x^i\|_{s,u}\\
\lesssim&\delta^{1/2}+\delta^{l_0+p_0\varepsilon_k}\|Z^{m_0}\upsilon\|_{s,u}
+(\delta^{k(1-\varepsilon_0)}+\delta^{\varepsilon_k})\sum_{j=1}^2\delta^{l_0+p_0\varepsilon_k}\|Z^{m_0}\check L^j\|_{s,u}\\
&+\delta\delta^{l_{0}+p_0\varepsilon_k}\|Z^{m_{0}}\mu\|_{s,u}
+\delta^{2k(1-\varepsilon_0)+\varepsilon_0}\bigl( \sqrt{\mathcal E_{1,\leq m+2}(s,u)} + \sqrt{\mathcal E_{2,\leq m+2}(s,u)} \bigr).
\end{split}
\end{equation}
In addition, by \(\slashed{\mathcal L}_{\varrho\mathring L}R=\varrho\leftidx{^{(R)}}{\slashed\pi}_{\mathring L}\), \(\slashed{\mathcal L}_TR=\leftidx{^{(R)}}{\slashed\pi}_T\) and \eqref{Rpi}, it holds that
\begin{equation}\label{ZR}
\begin{split}
&\delta^{l+p\varepsilon_k}\|\slashed{\mathcal L}_Z^{m+1}R\|_{s,u}\\
\lesssim&\delta^{\varepsilon_0+1/2}+(\delta^{2k(1-\varepsilon_0)}+\delta^{\varepsilon_0})\delta^{l_0
+p_0\varepsilon_k}\|Z^{m_0}x\|_{s,u}+\delta^{k(1-\varepsilon_0)}\delta^{l_1+p_1\varepsilon_k}\|Z^{m_1}\upsilon\|_{s,u}\\
&+\delta^{\varepsilon_k}\delta^{l_1+p_1\varepsilon_k}\|Z^{m_1}\operatorname{tr}\check{\mathscr X}\|_{s,u}+(\delta^{2k(1-\varepsilon_0)}+\delta^{\varepsilon_k})\sum_{j=1}^2\delta^{l_1+p_1\varepsilon_k}\|Z^{m_1}\check L^j\|_{s,u}\\
&+(\delta^{\varepsilon_0}+\delta^{2k(1-\varepsilon_0)})\delta^{l_1+p_1\varepsilon_k}\|\slashed{\mathcal L}_Z^{m_1}\slashed g\|_{s,u}+\delta^{1+k(1-\varepsilon_0)}\delta^{l_{0}+p_0\varepsilon_k}\|Z^{m_{0}}\mu\|_{s,u}\\
&+\delta^{\varepsilon_0+2k(1-\varepsilon_0)}\bigl(\sqrt{\mathcal E_{1,\leq m+2}(s,u)} + \sqrt{\mathcal E_{2,\leq m+2}(s,u)}\bigr).
\end{split}
\end{equation}
On the other hand, from \eqref{omega}, \eqref{rrho} and the relations \(\slashed{\mathcal L}_{\varrho\mathring L}\slashed g=2\varrho\chi\), \(\slashed{\mathcal L}_T\slashed g=\leftidx{^{(T)}}{\slashed\pi}\), \(\slashed{\mathcal L}_R\slashed g=\leftidx{^{(R)}}{\slashed\pi}\), we have
\begin{equation}\label{Zku}
\begin{split}
\delta^{l+p\varepsilon_k}\|Z^{m+1}\upsilon\|_{s,u}
\lesssim& \delta^{k(1-\varepsilon_0)}\delta^{l_0+p_0\varepsilon_k}\|Z^{m_0}x\|_{s,u}+\sum_{i=1}^2\delta^{l_0+p_0\varepsilon_k}\|Z^{m_0}\check L^i\|_{s,u}\\
&+\delta^{k(1-\varepsilon_0)+\varepsilon_0}\bigl( \sqrt{\mathcal E_{1,\leq m+2}(s,u)} + \sqrt{\mathcal E_{2,\leq m+2}(s,u)} \bigr),
\end{split}
\end{equation}
\begin{equation}\label{Zkr}
\begin{split}
\delta^{l+p\varepsilon_k}\|Z^{m+1}\check\varrho\|_{s,u}
\lesssim & \delta^{k(1-\varepsilon_0)}\delta^{l_0+p_0\varepsilon_k}\|Z^{m_0}x\|_{s,u}
+\sum_{i=1}^2\delta^{l_0+p_0\varepsilon_k}\|Z^{m_0}\check L^i\|_{s,u}\\
&+\delta^{2k(1-\varepsilon_0)+1/2}+ \delta^{k(1-\varepsilon_0)+\varepsilon_0}\bigl(\sqrt{\mathcal E_{1,\leq m+2}(s,u)} + \sqrt{\mathcal E_{2,\leq m+2}(s,u)}\bigr),
\end{split}
\end{equation}
\begin{equation}\label{Zkg}
\begin{split}
\delta^{l+p\varepsilon_k}\|\slashed{\mathcal L}_Z^{m+1}\slashed g\|_{s,u}\lesssim&(\delta^{k(1-\varepsilon_0)}+\delta^{\varepsilon_k})\bigl(\delta^{1/2}
+\delta^{l_1+p_1\varepsilon_k}\|Z^{m_1}\operatorname{tr}\check{\mathscr X}\|_{s,u}\bigr)\\
&+\delta^{l_1+p_1\varepsilon_k}\|Z^{m_1}\upsilon\|_{s,u}+\delta\delta^{l_{0}+p_0\varepsilon_k}\|Z^{m_{0}}\mu\|_{s,u}\\
&+\delta^{2k(1-\varepsilon_0)}\sum_{i=1}^2\delta^{l_1+p_1\varepsilon_k}\|Z^{m_1}\check L^i\|_{s,u}+\delta^{k(1-\varepsilon_0)}\delta^{l_0+p_0\varepsilon_k}\|Z^{m_0}x\|_{s,u}\\
&+ \delta^{k(1-\varepsilon_0)+\varepsilon_0} \bigl(\sqrt{\mathcal E_{1,\leq m+2}(s,u)} + \sqrt{\mathcal E_{2,\leq m+2}(s,u)}\bigr).
\end{split}
\end{equation}
Combining \eqref{ZkL}--\eqref{Zkg} and using induction on the derivative orders yield
\begin{align}
\delta^{l+p\varepsilon_k}\|Z^{m+2}x^i\|_{s,u}\lesssim&\delta^{1/2}+\Pi(s,u),\label{Zk1x}\\
\delta^{l+p\varepsilon_k}\|\slashed{\mathcal L}_Z^{m+1}\slashed g\|_{s,u}\lesssim&\delta^{1/2}(\delta^{k(1-\varepsilon_0)}+\delta^{\varepsilon_k})+\Pi(s,u),\label{Zk1g}\\
\delta^{l+p\varepsilon_k}\bigl(\|Z^{m+1}\check L^i\|_{s,u}&+\|Z^{m+1}\upsilon\|_{s,u}+\|Z^{m+1}\check\varrho\|_{s,u}\bigr)\lesssim\delta^{k(1-\varepsilon_0)+1/2}+\Pi(s,u),\label{Zk1L}\\
\delta^{l+p\varepsilon_k}\|\slashed{\mathcal L}_Z^{m+1}R\|_{s,u}\lesssim& \delta^{1/2}(\delta^{\varepsilon_0}+\delta^{2k(1-\varepsilon_0)})+(\delta^{\varepsilon_k}
+\delta^{k(1-\varepsilon_0)})\delta^{l_{1}+p_1\varepsilon_k}\|Z^{m_1}\operatorname{tr}\check{\mathscr X}\|_{s,u}\nonumber\\
&+(\delta^{(3k+1)(1-\varepsilon_0)}+\delta^{1+k(1-\varepsilon_0)}+\delta^{1+\varepsilon_k})\delta^{l_{0}+p_0\varepsilon_k}\|Z^{m_{0}}\mu\|_{s,u}\nonumber\\
&+(\delta^{2k(1-\varepsilon_0)+\varepsilon_0}+\delta^{2\varepsilon_0})\bigl( \sqrt{\mathcal E_{1,\leq m+2}(s,u)} + \sqrt{\mathcal E_{2,\leq m+2}(s,u)} \bigr),\label{Zk1R}
\end{align}
where
\begin{align*}
\Pi(s,u)=&\delta^{l_1+p_1\varepsilon_k}\|Z^{m_1}\operatorname{tr}\check{\mathscr X}\|_{s,u}+\bigl( \delta + \delta^{(2k+1)(1-\varepsilon_0)} \bigr) \delta^{l_0+p_0\varepsilon_k} \| Z^{m_0}\mu \|_{s,u}\\
&+\delta^{k(1-\varepsilon_0)+\varepsilon_0}\bigl(\sqrt{\mathcal E_{1,\leq m+2}(s,u)} + \sqrt{\mathcal E_{2,\leq m+2}(s,u)}\bigr).
\end{align*}
Using \eqref{Lpi}--\eqref{Rpi}, one arrives at
\begin{align}
\delta^{l+p\varepsilon_k}\|\slashed{\mathcal L}_Z^{m}\leftidx{^{(R)}}{\slashed\pi}\|_{s,u}\lesssim&\delta^{k(1-\varepsilon_0)+ 1/2}+\Pi(s,u),\label{ZkRp}\\
\delta^{l+p\varepsilon_k}\|\slashed{\mathcal L}_Z^{m}\leftidx{^{(R)}}{\slashed\pi}_{\mathring L}\|_{s,u}\lesssim&(1+\delta^{2k(1-\varepsilon_0)-\varepsilon_0})\bigl(\delta^{k(1-\varepsilon_0)+1/2}+\Pi(s,u)\bigr),\label{ZkRLp}\\
\delta^{l+p\varepsilon_k}\|\slashed{\mathcal L}_Z^{m}\leftidx{^{(R)}}{\slashed\pi}_T\|_{s,u}\lesssim&\delta^{k(1-\varepsilon_0)-1}\bigl(\delta^{k(1-\varepsilon_0)+1/2}+\Pi(s,u)\bigr),\label{ZkRLpi}\\
\delta^{l+p\varepsilon_k}\|\slashed{\mathcal L}_Z^m\leftidx{^{(T)}}{\slashed\pi}\|_{s,u}\lesssim&\delta^{k(1-\varepsilon_0)-1}\delta^{l_1+p_1\varepsilon_k}\|Z^{m_1}\operatorname{tr}\check{\mathscr X}\|_{s,u}+(1+\delta^{3k(1-\varepsilon_0)-\varepsilon_0})\delta^{l_0+p_0\varepsilon_k} \| Z^{m_0}\mu \|_{s,u}\nonumber\\
&+\delta^{k(1-\varepsilon_0)-1/ 2}
+\delta^{(k-1)(1-\varepsilon_0)}\bigl(\sqrt{\mathcal E_{1,\leq m+2}(s,u)} + \sqrt{\mathcal E_{2,\leq m+2}(s,u)}\bigr) ,\label{ZkTpi}\\
\delta^{l+p\varepsilon_k}\|\slashed{\mathcal L}_Z^m\leftidx{^{(T)}}{\slashed\pi}_{\mathring L}\|_{s,u}\lesssim&\delta^{k(1-\varepsilon_0)-1}\delta^{l_1+p_1\varepsilon_k}\|Z^{m_1}\operatorname{tr}\check{\mathscr X}\|_{s,u}+(1+\delta^{2k(1-\varepsilon_0)-\varepsilon_0})\delta^{l_0+p_0\varepsilon_k} \| Z^{m_0}\mu \|_{s,u}\nonumber\\
&+\delta^{k(1-\varepsilon_0) -1/2}
+\delta^{(k-1)(1-\varepsilon_0)}\bigl(\sqrt{\mathcal E_{1,\leq m+2}(s,u)} + \sqrt{\mathcal E_{2,\leq m+2}(s,u)}\bigr).\label{ZkTLpi}
\end{align}

Note that all the terms on the left-hand sides of \eqref{Zk1x}--\eqref{ZkTLpi} are controlled by the \(L^2\)-norms of the derivatives of \(\operatorname{tr}{\check{\mathscr X}}\) and \(\mu\).
We now estimate \(\|Z^{m}\operatorname{tr}{\check{\mathscr X}}\|_{s,u}\) and \(\|Z^{m+1}\mu\|_{s,u}\).

It follows from \eqref{Tchi'} and \eqref{Zk1x}--\eqref{ZkTLpi} that when \(n_1+n_2=m-1\),
\begin{align}
&\delta^{1+l}\|\bar Z^{n_1} T R^{n_2}\operatorname{tr}{\check{\mathscr X}}\|_{s,u}\leq\delta^{1+l}\|\bar Z^{n_1}[T,R^{n_2}]\operatorname{tr}{\check{\mathscr X}}\|_{s,u}+\delta^{1+l}\|\bar Z^{n_1}R^{n_2}T\operatorname{tr}{\check{\mathscr X}}\|_{s,u}\nonumber\\
\lesssim & \delta^{k(1-\varepsilon_0)+1}\delta^{l_2}\bigl(\|\slashed{\mathcal L}_{\bar Z}^{m_2}\leftidx{^{(R)}}{\slashed\pi}_T\|_{s,u}+\|\slashed{\mathcal L}_{\bar Z}^{m_2}\leftidx{^{(T)}}{\slashed\pi}\|_{s,u}\bigr)+\delta^{(k-1)(1-\varepsilon_0)}\delta^{l_0}\|\bar Z^{m_0}\varphi\|_{s,u}\nonumber\\
&+\delta^{k(1-\varepsilon_0)}\bigl(\delta^{l_2}\|\bar Z^{m_2}\operatorname{tr}{\check{\mathscr X}}\|_{s,u}+\delta^{l_1}\|\slashed{\mathcal L}_{\bar Z}^{m_1}\slashed g\|_{s,u}+\sum_{i=1}^2\bigl(\delta^{l_1}\|\bar Z^{m_1}\check L^i\|_{s,u}+\delta^{l_0}\|\bar Z^{m_0}x^i\|_{s,u}\bigr)\bigr)\nonumber\\
&+\delta(1+\delta^{2k(1-\varepsilon_0)-\varepsilon_0})\delta^{l_0}\|\bar Z^{m_0}\mu\|_{s,u}\nonumber\\
\lesssim & \delta^{k(1-\varepsilon_0)+1/2}+\delta^{k(1-\varepsilon_0)}\delta^{l_2}\|\bar Z^{m_2}\operatorname{tr}{\check{\mathscr X}}\|_{s,u}+\delta(1+\delta^{2k(1-\varepsilon_0)-\varepsilon_0})\delta^{l_0}\|\bar Z^{m_0}\mu\|_{s,u}\label{barZTchi}\\
&+\delta^{k(1-\varepsilon_0)+\varepsilon_0} \bigl( \sqrt{\mathcal E_{1,\leq m+2}(s,u)} + \sqrt{\mathcal E_{2,\leq m+2}(s,u)}\bigr),\nonumber
\end{align}
where \(\bar Z\in\{T,R\}\) and \(l\) is the number of \(T\) in \(\bar Z^{n_1}\), \(0\leq m_2\leq m-1\),
and \(l_j\) counts the occurrences of \(T\) in \(\bar Z^{m_j}\). In what follows, \(l\) counts the occurrences of \(T\)
in the full string on the left-hand side.

In addition, commuting \eqref{lmu} with $\bar Z^{m+1}$ and estimating the resulting commutator yield
\begin{align}
&\delta^{l}\|\mathring L\bar Z^{m+1}\mu\|_{s,u}\nonumber\\
\lesssim & \delta^{2k(1-\varepsilon_0)-\varepsilon_0}\delta^{l_0}\|\bar Z^{m_0}\mu\|_{s,u}+\delta^{(k-1)(1-\varepsilon_0)}\delta^{l_0}\bigl(\|\mu\mathring L\bar Z^{m_0}\varphi\|_{s,u}+\|T\bar Z^{m_0}\varphi\|_{s,u}\bigr)\nonumber\\
&+\delta^{l_1}\bigl(\delta^{k(1-\varepsilon_0)}\|\slashed{\mathcal L}_{\bar Z}^{m_1}\leftidx{^{(R)}}{\slashed\pi}_{T}\|_{s,u}+\|\slashed{\mathcal L}_{\bar Z}^{m_1}\leftidx{^{(R)}}{\slashed\pi}_{\mathring L}\|_{s,u}+\delta\|\slashed{\mathcal L}_{\bar Z}^{m_1}\leftidx{^{(T)}}{\slashed\pi}_{\mathring L}\|_{s,u}\bigr)\nonumber\\
&+\delta^{k(1-\varepsilon_0)-1}\delta^{l_0}\bigl(\sum_{i=1}^2\|\bar Z^{m_0}\check L^i\|_{s,u}+\|\bar Z^{m_0}\upsilon\|_{s,u}\bigr)\nonumber\\
&+\delta^{3k(1-\varepsilon_0)-1}\delta^{l_1}\|\slashed{\mathcal L}_{\bar Z}^{m_1}\slashed g\|_{s,u}
+\delta^{(k-1)(1-\varepsilon_0)-1}\delta^{l_0}\|\bar Z^{m_0}\varphi\|_{s,u}\nonumber\\
\lesssim & \delta^{2k(1-\varepsilon_0)-\varepsilon_0}\delta^{l_0}\|\bar Z^{m_0}\mu\|_{s,u}+\delta^{2k(1-\varepsilon_0)-1/2}+\delta^{k(1-\varepsilon_0)-1}\delta^{l_1}\|\bar Z^{m_1}\operatorname{tr}{\check{\mathscr X}}\|_{s,u}\label{Lmu}\\
&+\delta^{(k-1)(1-\varepsilon_0)}\bigl(\sqrt{\mathcal E_{1,\leq m+2}(s,u)}+\sqrt{\mathcal E_{2,\leq m+2}(s,u)}\bigr).\nonumber
\end{align}
By the initial data estimates, applying \eqref{Ff} to \eqref{Lmu}, and then utilizing Gronwall's inequality, we obtain
\begin{equation}\label{m}
\begin{split}
    \delta^{l} \|\bar Z^{m+1} \mu \|_{s,u} \lesssim &\delta^{k(1-\varepsilon_0)+\varepsilon_0-1/2} + \delta^{(k-1)(1-\varepsilon_0)}\int_{t_0}^s \bigl(\sqrt{\mathcal E_{1,\leq m+2}(\tau,u)}+\sqrt{\mathcal E_{2,\leq m+2}(\tau,u)}\bigr)\,d\tau\\
    + & \delta^{k(1-\varepsilon_0)-1}\int_{t_0}^s\delta^{l_1}\|\bar Z^{m_1}\operatorname{tr}{\check{\mathscr X}}\|_{\tau,u}\,d\tau.
    \end{split}
\end{equation}
In addition, it follows from \eqref{barZTchi}, \eqref{m}, induction argument and Gronwall's inequality that for \(l\geq1\),
\begin{align}
    \delta^{l}\|\bar Z^{m}\operatorname{tr}{\check{\mathscr X}}\|_{s,u}\lesssim &\delta^{k(1-\varepsilon_0)+1/2}+\delta^{k(1-\varepsilon_0)+\varepsilon_0}\sum_{i=1}^2\sqrt{\mathcal E_{i,\leq m+2}(s,u)}\nonumber\\
    &+\delta^{k(1-\varepsilon_0)+\varepsilon_0}(1+\delta^{2k(1-\varepsilon_0)-\varepsilon_0})\sum_{i=1}^2\int_{t_0}^s\sqrt{\mathcal E_{i,\leq m+2}(\tau,u)}\,d\tau,\label{1lchi}\\
    \delta^{l}\|\bar Z^{m+1}\mu\|_{s,u}\lesssim & \delta^{k(1-\varepsilon_0)+\varepsilon_0-1/2} +  \delta^{(k-1)(1-\varepsilon_0)}\sum_{i=1}^2\int_{t_0}^s\sqrt{\mathcal E_{i,\leq m+2}(\tau,u)}\,d\tau.\label{1lmu}
\end{align}

For the remaining case, the derivative string contains at least one
$\varrho\mathring L$. In order to treat this case, we will use \eqref{Lchi'} and \eqref{lmu} directly,
and then apply the induction argument on the derivative orders and on the number of
occurrences of $\varrho\mathring L$.
Based on this, together with \eqref{1lchi}--\eqref{1lmu} and the estimates for
pure $R$ derivatives, one has that for $l+p\geq1$,
\begin{align}
    \delta^{l+p\varepsilon_k}\|Z^{m}\operatorname{tr}{\check{\mathscr X}}\|_{s,u}\lesssim &\delta^{k(1-\varepsilon_0)+1/2}+\delta^{k(1-\varepsilon_0)+\varepsilon_0}\sum_{i=1}^2\sqrt{\mathcal E_{i,\leq m+2}(s,u)}\nonumber\\
    &+\delta^{k(1-\varepsilon_0)+\varepsilon_0}(1+\delta^{2k(1-\varepsilon_0)-\varepsilon_0})\sum_{i=1}^2\int_{t_0}^s\sqrt{\mathcal E_{i,\leq m+2}(\tau,u)}\,d\tau,\label{1lpchi}\\
    \delta^{l+p\varepsilon_k}\|Z^{m+1}\mu\|_{s,u}\lesssim &\delta^{k(1-\varepsilon_0)+\varepsilon_0-1/2}
    +\delta^{(k-1)(1-\varepsilon_0)}\Xi^2_{m+2}(s,u)\nonumber\\
    &+\delta^{2\varepsilon_0-1}\sum_{i=1}^2
    \sqrt{\mathcal E_{i,\leq m+2}(s,u)}.\label{1lpmu}
\end{align}

Collecting all the estimates from \eqref{RmcX}, \eqref{RMMu}, \eqref{1lpchi}--\eqref{1lpmu} and \eqref{Zk1x}--\eqref{ZkTLpi},
we finish the proof of Proposition \ref{L2chi}.

\label{Cor6.3}
	Under the assumptions of Proposition~\ref{L2chi}, let
	$0\leq m\leq 2N-6$, $\bar Z\in\{T,R\}$ and $l$ denote the number of occurrences
	of $T$ in the corresponding derivative strings. Then
	\begin{align}
	\delta^l\|\bar Z^{m+1}\phi\|_{s,u}\lesssim & \delta^{5/2-\varepsilon_0}+\delta^{k(1-\varepsilon_0)+1}\Xi_{m+2}^2(s,u)+\delta^2\sum_{i=1}^2\sqrt{\mathcal E_{i,\leq m+2}(s,u)},\label{Zphi}\\
	\delta^l\|\bar Z^{m+1}\mathring L\phi\|_{s,u}\lesssim &\delta^{5/2-\varepsilon_0-\varepsilon_k}+\delta^{(2k+1)(1-\varepsilon_0)}\Xi^2_{m+2}(s,u)+\delta\sqrt{\mathcal E_{1,\leq m+2}(s,u)}\nonumber\\
	&+\delta^{(k+1)(1-\varepsilon_0)+1}\sqrt{\mathcal E_{2,\leq m+2}(s,u)}+\delta^{2-\varepsilon_0+k(1-\varepsilon_0)}\|R^m\slashed\triangle\mu\|_{s,u},\label{ZLphi}\\
	\delta^{l}\|\slashed{\mathcal L}_{\bar Z}^{m+1}\slashed{d}\phi\|_{s,u}\lesssim & \delta^{5/2-\varepsilon_0}+\delta\sqrt{\mathcal E_{1,\leq m+2}(s,u)}+\delta^2\sqrt{\mathcal E_{2,\leq m+2}(s,u)}\nonumber\\
	&+\delta^{2-\varepsilon _0}\|R^m\slashed\triangle\mu\|_{s,u}+\delta^{1+k(1-\varepsilon_0)}\Xi^2_{m+2}(s,u),\label{Zdphi}\\
	\delta^l\|\bar Z^m\mathring L^2\phi\|_{s,u}\lesssim & \delta^{5/2-\varepsilon_0-2\varepsilon_k}+\delta^{2-\varepsilon_0+2k(1-\varepsilon_0)}\|R^m\slashed\triangle\mu\|_{s,u}
+\delta^{1-\varepsilon_k}\sqrt{\mathcal E_{1,\leq m+2}(s,u)}\nonumber\\
&+\delta^{2(k+1)(1-\varepsilon_0)} \sqrt{\mathcal E_{2,\leq m+2}(s,u)}+\delta^{3k(1-\varepsilon_0)-2\varepsilon_0+1}\Xi_{m+2}^2(s,u).\label{ZLLphi}
\end{align}
Moreover,
\begin{align}
\delta^l\|\bar Z^{m+1}(G_{\mathring L\mathring L}^\gamma\mathring L_\gamma)\|_{s,u}
\lesssim&\delta^{k(1-\varepsilon_0)}\Bigl\{\delta^{1/2}+\delta^{\varepsilon_0}\|R^m\slashed\triangle\mu\|_{s,u}+\delta^{2\varepsilon_0-1}\sqrt{\mathcal E_{1,\leq m+2}(s,u)}\nonumber\\
&\qquad\qquad+\delta^{\varepsilon_0}\sqrt{\mathcal E_{2,\leq m+2}(s,u)}
+\delta^{(k-1)(1-\varepsilon_0)}\Xi^1_{m+2}(s,u)\Bigr\},\label{ZGL}\\
\delta^l\|\bar Z^m\mathring L\phi\|_{s,u}
\lesssim&\delta^{(k+2)(1-\varepsilon_0)+1/2}+\delta\sqrt{\mathcal E_{1,\leq m+2}(s,u)}\nonumber\\
&+\delta^{(k+1)(1-\varepsilon_0)+1}\sqrt{\mathcal E_{2,\leq m+2}(s,u)}+\delta^{(2k+1)(1-\varepsilon_0)}\Xi^2_{m+2}(s,u).\label{ZmLphi}
\end{align}

From \eqref{SiSi}, we have
\begin{equation}\label{lowerphi}
\begin{split}
\delta^l\|\bar Z^{m+1}\phi\|_{s,u}&\lesssim \delta^{1+l}\|T\bar Z^{m+1}\phi\|_{s,u}\\
&\lesssim \delta^{l+1}\bigl(\|[T,\bar Z^{m+1}]\phi\|_{s,u}+\|\bar Z^{m+1}(\mu\tilde T^i\varphi_i)\|_{s,u}\bigr)\\
&\lesssim \delta^{3-\varepsilon_0}\delta^{l_1}\|\slashed{\mathcal L}_{\bar Z}^{m_1}\leftidx{^{(R)}}{\slashed\pi}_T\|_{s,u}+\delta^{2k(1-\varepsilon_0)}\delta^{l_0}\|\bar Z^{m_0}\phi\|_{s,u}\\
&\quad+\delta^{(2k+1)(1-\varepsilon_0)+1}\delta^{l_1}\|\slashed{\mathcal L}_{\bar Z}^{m_1}\slashed g\|_{s,u}+\delta\delta^{l_0}\|\bar Z^{m_0}\varphi\|_{s,u}\\
&\quad+\delta^{2-\varepsilon_0}\delta^{l_0}\bigl(\|\bar Z^{m_0}\mu\|_{s,u}+\sum_{i=1}^2(\|\bar Z^{m_0}\check L^i\|_{s,u}+\|\bar Z^{m_0}x^i\|_{s,u})\bigr).
\end{split}	
\end{equation}
Absorbing the term $\delta^{2k(1-\varepsilon_0)}\delta^{l_0}\|\bar Z^{m_0}\phi\|_{s,u}$ on the right-hand side by the left-hand side
in \eqref{lowerphi}, one has
\begin{align*}
\delta^l\|\bar Z^{m+1}\phi\|_{s,u}
\lesssim & \ \delta^{3-\varepsilon_0}\delta^{l_1}\|\slashed{\mathcal L}_{\bar Z}^{m_1}\leftidx{^{(R)}}{\slashed\pi}_T\|_{s,u}
+\delta^{(2k+1)(1-\varepsilon_0)+1}\delta^{l_1}\|\slashed{\mathcal L}_{\bar Z}^{m_1}\slashed g\|_{s,u}\\
&+\delta^{2-\varepsilon_0}\delta^{l_0}\bigl(\|\bar Z^{m_0}\mu\|_{s,u}+\sum_{i=1}^2(\|\bar Z^{m_0}\check L^i\|_{s,u}+\|\bar Z^{m_0}x^i\|_{s,u})\bigr)+\delta\delta^{l_0}\|\bar Z^{m_0}\varphi\|_{s,u}\\
\lesssim & \ \delta^{5/2-\varepsilon_0}+\delta^{k(1-\varepsilon_0)+1}\Xi_{m+2}^2(s,u)+\delta^2\sum_{i=1}^2\sqrt{\mathcal E_{i,\leq m+2}(s,u)}.
\end{align*}
We next estimate $\bar Z^{m+1}\mathring L\phi$. When $\bar Z^{m+1}=R^{m+1}$, using \eqref{SiSi} gives
\begin{align}
\|R^{m+1}\mathring L\phi\|_{s,u}&\lesssim\delta\|TR^{m+1}\mathring L\phi\|_{s,u}\nonumber\\
&\lesssim \delta\|R^{m+1}T(\mathring L^\alpha\varphi_\alpha)\|_{s,u}+\delta^{1+(k+2)(1-\varepsilon_0)}\|\slashed{\mathcal L}_{R}^{m_1}\leftidx{^{(R)}}{\slashed\pi}_T\|_{s,u}\label{ZLp}\\
&\quad+\delta^{2k(1-\varepsilon_0)}\|R^{m_0}\mathring L\phi\|_{s,u}+\delta^{(3k+2)(1-\varepsilon_0)}\|\slashed{\mathcal L}_{R}^{m_1}\leftidx{^{(R)}}{\slashed\pi}\|_{s,u},\nonumber
\end{align}
where $T(\mathring L^\alpha \varphi_\alpha)=(T\mathring L^i)\varphi_i+\mu\tilde T^i(\mathring L\varphi_i)$.
Recalling that $T\mathring L^i$ satisfies \eqref{TL}, we have
\begin{equation}\label{TLp}
T(\mathring L^\alpha \varphi_\alpha)=\mu\tilde T^i(\mathring L\varphi_i)+(\slashed d_X\mu)\slashed d^X\phi-(G_{X\mathring L}^\gamma T\varphi_\gamma)\slashed d^X\phi+\frac12(G_{\mathring L\mathring L}^\gamma T\varphi_\gamma)\tilde T^i\varphi_i+\dots.
\end{equation}
With the help of \eqref{GT} and \eqref{gLLL}, substituting \eqref{TLp} into \eqref{ZLp} yields
\begin{align}
&\|R^{m+1}\mathring{L}\phi\|_{s,u}\nonumber\\
\lesssim&\ \delta^{(k+1)(1-\varepsilon_0)}\Bigl(\sum_{i=1}^2\|R^{m_0}\check{L}^i\|_{s,u}+\|R^{m_0}\check{\varrho}\|_{s,u}
+\|R^{m_0}\varphi\|_{s,u}+\delta\|TR^{m_0}\varphi\|_{s,u}\Bigr)\nonumber\\
&+\delta^{(k+2)(1-\varepsilon_0)}\bigl(\|R^{m_{-1}}x\|_{s,u}+\|R^{m_0}\mu\|_{s,u}\bigr)
+\delta^{k(1-\varepsilon_0)+1}\|\mu\slashed{d}R^{m_0}\varphi\|_{s,u}\nonumber\\
&+\delta\|\mu\mathring{L}R^{m_0}\varphi\|_{s,u}
+\delta^{(k+2)(1-\varepsilon_0)+1}\|\slashed{\mathcal{L}}_{R}^{m_1}\,{}^{(R)}\!\slashed{\pi}_T\|_{s,u}
+\delta^{k(1-\varepsilon_0)}\|\slashed{d}R^{m_0}\phi\|_{s,u}\nonumber\\
&+\delta^{3-\varepsilon_0}\|\slashed{d}R^{m+1}\mu\|_{s,u}
+\delta^{(k+1)(1-\varepsilon_0)}(\delta+\delta^{(2k+1)(1-\varepsilon_0)})\|\slashed{\mathcal L}_{R}^{m_1}\leftidx{^{(R)}}{\slashed\pi}\|_{s,u}\nonumber\\
&+\delta^{2-\varepsilon_0}\|\slashed{\mathcal{L}}_{R}^{m_1}\,{}^{(R)}\!\slashed{\pi}_{\mathring{L}}\|_{s,u}
+\delta^{3-\varepsilon_0}\|\slashed{\mathcal{L}}_{R}^{m_1}\,{}^{(T)}\!\slashed{\pi}_{\mathring{L}}\|_{s,u}\nonumber\\
\lesssim&\ \delta^{(k+2)(1-\varepsilon_0)+1/2}+\delta^{(2k+1)(1-\varepsilon_0)}\Xi^2_{m+2}(s,u)+\delta\sqrt{\mathcal E_{1,\leq m+2}(s,u)}\nonumber\\
&+\delta^{(k+1)(1-\varepsilon_0)+1}\sqrt{\mathcal E_{2,\leq m+2}(s,u)}+\delta^{3-\varepsilon_0}\|R^m\slashed\triangle\mu\|_{s,u}+\delta^{k(1-\varepsilon_0)}\|\slashed{d}R^{m_0}\phi\|_{s,u},\nonumber
\end{align}
where $1\leq m_p\leq m+1-p$ with $p=-1,0,1$. If $\bar Z^{m+1}=\bar Z^{p_1}TR^{p_2}$ with $p_1+p_2=m$, then $\bar Z^{m+1}\mathring L\phi=\bar Z^{p_1}R^{p_2}T(\mathring L^\alpha\varphi_\alpha)+\bar Z^{p_1}[T,R^{p_2}]\mathring L\phi$. Hence, for any $\bar Z^{m+1}$ containing $l$ occurrences of the vector field $T$, one has
\begin{equation}\label{bZLp}
\begin{split}
\delta^l\|\bar Z^{m+1}\mathring L\phi\|_{s,u}
\lesssim & \ \delta^{(k+2)(1-\varepsilon_0)+1/2}+\delta^{(2k+1)(1-\varepsilon_0)}\Xi^2_{m+2}(s,u)+\delta\sqrt{\mathcal E_{1,\leq m+2}(s,u)}\\
&+\delta^{(k+1)(1-\varepsilon_0)+1}\sqrt{\mathcal E_{2,\leq m+2}(s,u)}+\delta^{3-\varepsilon_0}\|R^m\slashed\triangle\mu\|_{s,u}\\
&+\delta^{k(1-\varepsilon_0)}\delta^{l_0}\|\slashed{d}\bar Z^{m_0}\phi\|_{s,u}.
\end{split}
\end{equation}



In addition, due to $|\slashed{\mathcal L}_{\bar Z}^{m+1}\slashed d\phi|\lesssim |R\bar Z^{m+1}\phi|$, it suffices to
treat the $L^2$ norm of $R\bar Z^{m+1}\phi$. As before, for $\bar Z^{m+1}=R^{m+1}$, we have
\begin{equation}\label{Rp}
\begin{split}
\|R^{m+2}\phi\|_{s,u}
\lesssim & \ \delta\|R^{m+1}TR\phi\|_{s,u}+\delta^{3-\varepsilon_0}\|\slashed{\mathcal L}_{R}^{m_1}\leftidx{^{(R)}}{\slashed\pi}_T\|_{s,u}+\delta^{2k(1-\varepsilon_0)}\|R^{m_0}R\phi\|_{s,u}\\
&+\delta^{2k(1-\varepsilon_0)+2-\varepsilon_0}\|\slashed{\mathcal L}_{R}^{m_1}\leftidx{^{(R)}}{\slashed\pi}\|_{s,u}.
\end{split}
\end{equation}
Note that $TR\phi=\leftidx{^{(R)}}{\slashed\pi}_{TX}\slashed d^X\phi+(R\mu)\tilde T^i\varphi_i-\mu(Rg^{0i})\varphi_i-\mu(R\mathring L^i)\varphi_i+\mu \tilde T^iR\varphi_i$. It follows from \eqref{Rpi} and \eqref{deL} that
\begin{equation*}
\begin{split}
TR\phi=&\ \upsilon\slashed d^X\mu\slashed d_X\phi+\mu(G_{X\mathring L}^\gamma R\varphi_\gamma)\slashed d^X\phi+\mu(G_{X\tilde T}^\gamma R\varphi_\gamma)\slashed d^X\phi+\mu\epsilon_i^a\check T^ig_{ab}(\slashed d_Xx^b\slashed d^X\phi)\\
&-\frac{\mu}{\varrho}R\phi+\upsilon(G_{X\tilde T}^\gamma T\varphi_\gamma)\slashed d^X\phi-\frac12\upsilon\mu(G_{\tilde T\tilde T}^\gamma\slashed d^X\varphi_\gamma)\slashed d_X\phi+\mu(G_{\mathring L\tilde T}^\gamma R\varphi_\gamma)\tilde T^i\varphi_i\\
&+\frac12\mu(G_{\tilde T\tilde T}^\gamma R\varphi_\gamma)\tilde T^i\varphi_i+(R\mu)\tilde T^i\varphi_i-\mu(Rg^{0i})\varphi_i+\mu \tilde T^iR\varphi_i.
\end{split}
\end{equation*}
Thus,
\begin{align}
\|R^{m+2}\phi\|_{s,u}
\lesssim&\ \delta^{2-\varepsilon_0}\bigl\{\|\slashed dR^{m+1}\mu\|_{s,u}+\|R^{m_0}\mu\|_{s,u}\bigr\}+\delta^{3-\varepsilon_0}\|\slashed{\mathcal L}_{R}^{m_1}\leftidx{^{(R)}}{\slashed\pi}_T\|_{s,u}\nonumber\\
&+\delta\|R^{m_0}\varphi\|_{s,u}+\delta \|\mu\slashed dR^{m+1}\varphi\|_{s,u}+\delta^{2k(1-\varepsilon_0)+2}\|TR^{m+1}\varphi\|_{s,u}\nonumber\\
&+\delta^{(k+1)(1-\varepsilon_0)+1}\|R^{m_0}\upsilon\|_{s,u}+\delta^{(2k+1)(1-\varepsilon_0)+1}\|\slashed{\mathcal L}_{R}^{m_1}\leftidx{^{(R)}}{\slashed\pi}\|_{s,u}\nonumber\\
&+\delta^{2-\varepsilon_0}\sum_{i=1}^2\bigl(\|R^{m_0}\check L^i\|_{s,u}+\|R^{m_{-1}}x^i\|_{s,u}\bigr)\nonumber\\
\lesssim & \ \delta^{5/2-\varepsilon_0}+\delta\sqrt{\mathcal E_{1,\leq m+2}(s,u)}+\delta^2\sqrt{\mathcal E_{2,\leq m+2}(s,u)}\label{Rmp}\\
&+\delta^{2-\varepsilon _0}\|R^m\slashed\triangle\mu\|_{s,u}+\delta^{1+k(1-\varepsilon_0)}\Xi^2_{m+2}(s,u).\nonumber
\end{align}
For $\bar Z^{m+1}=\bar Z^{p_1}TR^{p_2}$ with $p_1+p_2=m$, due to $R\bar Z^{m+1}\phi=R\bar Z^{p_1}R^{p_2}(\mu \tilde T^i\varphi_i)+R\bar Z^{p_1}[T,R^{p_2}]\phi$, one has
\begin{equation}\label{DXY-8}
\begin{split}
\delta^l\|R\bar Z^{m+1}\phi\|_{s,u}
\lesssim & \ \delta^{3-\varepsilon_0}\delta^{l_1}\|\slashed{\mathcal L}_{\bar Z}^{m_1}\leftidx{^{(R)}}{\slashed\pi}_T\|_{s,u}+\delta^{2k(1-\varepsilon_0)}\delta^{l_0}\|\bar Z^{m_0}\phi\|_{s,u}+\delta^{(2k+1)(1-\varepsilon_0)+1}\delta^{l_1}\|\slashed{\mathcal L}_{\bar Z}^{m_1}\slashed g\|_{s,u}\\
&+\delta^{2-\varepsilon_0}\delta^{l_0}\bigl(\|\bar Z^{m_0}\mu\|_{s,u}+\sum_{i=1}^2(\|\bar Z^{m_0}\check L^i\|_{s,u}+\|\bar Z^{m_0}x^i\|_{s,u})\bigr)+\delta\delta^{l_0}\|\bar Z^{m_0}\varphi\|_{s,u}.
\end{split}
\end{equation}
Note that the terms on the right-hand side in \eqref{DXY-8} are exactly the same as the ones in \eqref{lowerphi}. Therefore,
we can obtain \eqref{Zdphi}, and then \eqref{ZLphi} follows by substituting \eqref{Zdphi} into \eqref{bZLp}.



Analogously, owing to
\[
\|R^m\mathring L^2\phi\|_{s,u}
\lesssim \delta\bigl\|[T,R^m\mathring L]\mathring L\phi\bigr\|_{s,u}
+\delta\bigl\|R^m\mathring L T\bigl(\mathring L^\alpha\varphi_\alpha\bigr)\bigr\|_{s,u},
\]
one deduces from \eqref{TLp} that
\begin{align*}
&\|R^m\mathring L^2\phi\|_{s,u}\\
\lesssim &\delta^{1-\varepsilon_k}\biggl(
\sum_{i=1}^2\bigl(\delta^{-\varepsilon_k}\|R^{m_0}\check L^i\|_{s,u}
+\|R^{m_1}\mathring L\check L^i\|_{s,u}\bigr)
+\delta^{-\varepsilon_k}\|R^{m_0}\check\varrho\|_{s,u}
+\|R^{m_1}\mathring L\check\varrho\|_{s,u}
\biggr)\\
&+\delta^{(2k+2)(1-\varepsilon_0)-\varepsilon_0}\|R^{m_{0}}x\|_{s,u}
+\delta^{3-\varepsilon_0-\varepsilon_k}
\bigl\|\slashed{\mathcal L}_{R}^{m_1} \leftidx{^{(T)}}{\slashed\pi}_{\mathring L}\bigr\|_{s,u}+\delta^{3-\varepsilon_0-2\varepsilon_k}
\bigl\|\slashed{\mathcal L}_{R}^{m_1} \leftidx{^{(R)}}{\slashed\pi}_T\bigr\|_{s,u}\\
&+\delta^{k(1-\varepsilon_0)}\|R^{m_0}\mathring L\phi\|_{s,u}+\delta^{k(1-\varepsilon_0)-\varepsilon_k}\|R^{m_0}\phi\|_{s,u}
+\delta^{3-\varepsilon_0}\bigl\|\slashed d R^{m}\mathring L\mu\bigr\|_{s,u}\\
&+\delta^{2-\varepsilon_0-\varepsilon_k}\|R^{m_1}\mathring L\mu\|_{s,u}
+\delta^{2-\varepsilon_0-2\varepsilon_k}\|R^{m_0}\mu\|_{s,u}+\delta^{2-\varepsilon_0-\varepsilon_k}
\bigl\|\slashed{\mathcal L}_{R}^{m_1} \leftidx{^{(R)}}{\slashed\pi}_{\mathring L}\bigr\|_{s,u}\\
&+\delta^{1-\varepsilon_k}\sqrt{\mathcal E_{1,\leq m+2}(s,u)}+\delta^{2(k+1)(1-\varepsilon_0)} \sqrt{\mathcal E_{2,\leq m+2}(s,u)}\\
\lesssim & \delta^{5/2-\varepsilon_0-2\varepsilon_k}
+\delta^{2-\varepsilon_0+2k(1-\varepsilon_0)}\|R^m\slashed\triangle\mu\|_{s,u}+\delta^{1-\varepsilon_k}\sqrt{\mathcal E_{1,\leq m+2}(s,u)}\\
&+\delta^{2(k+1)(1-\varepsilon_0)} \sqrt{\mathcal E_{2,\leq m+2}(s,u)}+\delta^{3k(1-\varepsilon_0)-2\varepsilon_0+1}\Xi_{m+2}^2(s,u).
\end{align*}


Meanwhile, it follows from \eqref{gLLL} that
\begin{align*}
\delta^l\bigl\lVert\bar{Z}^{m+1}\bigl(G_{\mathring{L}\mathring{L}}^\gamma \mathring{L}\gamma\bigr)\bigr\rVert
&\lesssim \delta^{(k-1)(1-\varepsilon_0)}\delta^{l_0}\bigl(
\lVert\bar{Z}^{m_0}\varphi\rVert{s,u}
\sum_{i=1}^2\lVert\bar{Z}^{m_0}\check{L}^i\rVert_{s,u}
\lVert\bar{Z}^{m_0}\check{\varrho}\rVert_{s,u}
\bigr) \\
&\quad + \delta^{k(1-\varepsilon_0)}\delta^{l_{-1}}\lVert\bar{Z}^{m_{-1}}x\rVert_{s,u}
\delta^{(k-2)(1-\varepsilon_0)}\delta^{l_0}\bigl(
\lVert\bar{Z}^{m_0}\mathring{L}\phi\rVert_{s,u}
\lVert\slashed{d}\bar{Z}^{m_0}\phi\rVert_{s,u}
\bigr).
\end{align*}
Together with Proposition \ref{L2chi} and the estimates \eqref{ZLphi}--\eqref{Zdphi}, this yields \eqref{ZGL}.
In addition, \eqref{ZmLphi} follows from \eqref{ZLphi} and Proposition \ref{L2chi}.
